__mod["app.controller"] = function(...)
-- App controller: wires the model to fb (core polling, run state and events, UI slots, actions).
-- Everything the UI shows comes from view.view(); everything the user changes goes through
-- detect.set_place / model.corrections and the run (state and events), never into the view directly.
local util = require("model.util")
local rules = require("model.rules")
local state = require("model.state")
local detect = require("model.detect")
local snapshot = require("model.snapshot")
local events = require("model.events")
local corrections = require("model.corrections")
local view_mod = require("model.view")
local oras = require("data.oras")
local common = require("ui.common")
local corr_ui = require("ui.corrections")
local panel = require("ui.panel")
local hud = require("ui.hud")
local screen = require("ui.screen")
local tile = require("ui.tile")
local board = require("ui.board")
local sync = require("app.sync")

local A = {}
A.__index = A

A.POLL_MS = 500      -- team, place, battle, badges
A.BOX_MS = 5000      -- boxes
A.RENDER_MS = 250    -- at most 4 UI refreshes per second
A.BOARD_MS = 5000    -- run board
A.HUD_MS = 3000      -- HUD stays expanded after a linked death
A.NOTICE_TRIES = 40  -- renders to wait for the state that shows a death

function A.new(fb)
  local self = setmetatable({}, A)
  self.fb = fb
  self.tr = function(key, vars) return fb.i18n.t(key, vars) end
  self.ui = { screen_tab = 1 }
  self.events, self.seen = {}, {}
  self.queue = {}          -- death events waiting for the view
  self.tiles, self.tile_slots = {}, {}
  self.sync = sync.new(fb)
  self.last_poll, self.last_box, self.last_render, self.last_board = -1e9, -1e9, -1e9, -1e9
  self.dirty = true
  self.errors = {}
  return self
end

local function warn_once(self, key, ...)
  if not self.errors[key] then
    self.errors[key] = true
    self.fb.log.warn(...)
  end
end

-- ---------------------------------------------------------------- start

function A:start()
  local fb, tr = self.fb, self.tr
  fb.ui.on_action(function(action, value, slot) self:on_action(action, value, slot) end)
  if not fb.run then
    self.sync:push("panel", panel.empty(tr))
    self.sync:push("hud", hud.empty(tr))
    self.sync:push("screen", screen.empty(tr))
    return
  end
  self.run = fb.run.current()
  self.me = self.run.me
  self.viewing = self.run.view == true -- run view of the Runs screen: shell context, read only
  -- run view: no game, so no core calls, no tracking, no notices; only the `run` slot shows the run
  if self.viewing then self.sync:push("screen", screen.empty(tr)) end
  self.st = state.ensure(util.copy(fb.run.state()))
  self.last_enc = (not self.viewing and fb.run.state()) and util.encode(self.st) or nil
  self:load_events()
  self.live = not self.viewing
  fb.run.on("event", function(ev) self:on_event(ev) end)
  fb.run.on("state", function() self.dirty = true end)
  fb.run.on("participants", function() self.dirty = true end)
  fb.run.on("status", function() self.dirty = true end)
  if not self.viewing then
    fb.events.on("fb", "tiles", function(list) self.tiles = type(list) == "table" and list or {}; self.dirty = true end)
  end
  fb.on_tick(function() self:tick() end)
  self:poll(true)
  self:render()
end

function A:load_events()
  local after = 0
  while true do
    local page = self.fb.run.events(after, 500)
    for _, ev in ipairs(page) do
      if not self.seen[ev.seq] then
        self.seen[ev.seq] = true
        self.events[#self.events + 1] = ev
      end
      after = math.max(after, ev.seq)
    end
    if #page < 500 then break end
  end
end

function A:writable() return common.writable(self.run) end

-- ---------------------------------------------------------------- ticking

function A:tick()
  local now = self.fb.clock()
  if self.writable_cached ~= self:writable() then
    self.writable_cached = self:writable()
    self.dirty = true
  end
  if now - self.last_poll >= A.POLL_MS then
    local full = now - self.last_box >= A.BOX_MS
    self.last_poll = now
    if full then self.last_box = now end
    local ok, err = pcall(self.poll, self, full)
    if not ok then warn_once(self, "poll", "poll failed: " .. tostring(err)) end
  end
  if self.hud_until and now >= self.hud_until then
    self.hud_until, self.hud_text = nil, nil
    self.dirty = true
  end
  if self.board_due and now - self.last_board >= A.BOARD_MS then self.dirty = true end
  if self.dirty and now - self.last_render >= A.RENDER_MS then
    local ok, err = pcall(self.render, self)
    if not ok then warn_once(self, "render", "render failed: " .. tostring(err)) end
  end
end

-- ---------------------------------------------------------------- polling and state

function A:poll(full)
  if not self:writable() then return end
  local cfg = rules.parse(self.run)
  local snap = snapshot.from_core(self.fb, { skip_boxes = (not full) and self.boxes ~= nil, boxes = self.boxes })
  if snap.boxes then self.boxes = snap.boxes end
  local game = self.fb.game or {}
  local st, facts = detect.diff(self.st, snap, cfg, { game = { id = game.code, language = game.language } })
  self:commit(st, facts)
end

--- Adopt a new own state, publish it when it changed and post the facts as automatic events.
function A:commit(st, facts)
  state.guard(st)
  self.st = st
  local enc = util.encode(st)
  if enc ~= self.last_enc then
    if self:writable() then
      local ok, why = self.fb.run.setState(st)
      if ok then self.last_enc = enc else warn_once(self, "setState", "setState refused: " .. tostring(why)) end
    end
    self.dirty = true
  end
  for _, f in ipairs(facts or {}) do self:post_fact(f) end
  if facts and #facts > 0 then self.dirty = true end
end

function A:player_name(id)
  for _, p in ipairs(self.run.participants or {}) do
    if p.user_id == id then return p.name or p.user_name or id end
  end
  return tostring(id)
end

function A:place_text(route)
  return route and oras.label(route, self.tr) or self.tr("place_none")
end

function A:fact_text(f)
  local tr = self.tr
  local player = self:player_name(self.me)
  local mon = common.mon_name({ nickname = f.nickname, species = f.species })
  local text
  if f.kind == "catch" then
    text = tr("ev_catch", { player = player, mon = mon, place = self:place_text(f.route) })
  elseif f.kind == "death" then
    text = tr("ev_death", { player = player, mon = mon })
  elseif f.kind == "encounter" then
    text = tr("ev_encounter", { player = player, mon = "#" .. tostring(f.species or "?"), place = self:place_text(f.route) })
  elseif f.kind == "missed" then
    text = tr("ev_missed", { player = player, place = self:place_text(f.route) })
  elseif f.kind == "place" then
    text = tr("ev_place", { player = player, place = f.key and self:place_text(f.key) or (f.name or tr("place_none")) })
  end
  if text and f.why then text = text .. " " .. tr("ev_why_" .. f.why) end
  return text and util.clean_text(text, 280) or nil
end

function A:post_fact(f)
  local spec = events.from_fact(f, self.me)
  if not spec or not self:writable() then return end
  spec.text = self:fact_text(f)
  local ok, err = pcall(self.fb.run.event, spec)
  if not ok then warn_once(self, "event", "event refused: " .. tostring(err)) end
  if f.kind == "place" and f.key and not f.manual then self:note_place(f.key) end
end

-- ---------------------------------------------------------------- events and notices

function A:on_event(ev)
  if type(ev) ~= "table" or self.seen[ev.seq] then return end
  self.seen[ev.seq] = true
  local n = #self.events
  self.events[n + 1] = ev
  if n > 0 and self.events[n].seq > ev.seq then
    table.sort(self.events, function(a, b) return a.seq < b.seq end)
  end
  self.dirty = true
  if not self.live then return end
  local p = type(ev.payload) == "table" and ev.payload or {}
  if ev.type == events.TYPES.death then
    self.queue[#self.queue + 1] = { ev = ev, tries = 0 }
  elseif ev.type == events.TYPES.catch and ev.user_id ~= self.me and p.counts then
    self:notify({ tone = "info", text = self.tr("note_catch", {
      player = self:player_name(ev.user_id), mon = common.mon_name({ nickname = p.nickname, species = p.species }),
      place = self:place_text(p.route) }) })
  end
end

function A:notify(n)
  n.title = n.title or self.tr("note_title")
  local ok, id = pcall(self.fb.ui.notify, n)
  if not ok then warn_once(self, "notify", "notify failed: " .. tostring(id)) end
  return ok and id or nil
end

function A:note_place(route)
  local row = self.view and common.row_of(self.view, route)
  local cell = row and row.cells[self.me]
  if cell and cell.state ~= "open" then return end
  self:notify({ tone = "info", text = self.tr("note_new_place", { place = self:place_text(route) }) })
end

-- Deaths in the own link groups: toast (important) and HUD expansion.
function A:process_queue(view)
  local keep = {}
  local groups = common.groups(view)
  for _, q in ipairs(self.queue) do
    local ev, p = q.ev, q.ev.payload or {}
    local owner = common.player(view, ev.user_id)
    local mon = owner and owner.mons[p.mon]
    local g = mon and mon.group and groups[mon.group]
    local handled = false
    if g and g.state == "dead" then
      local mine
      for _, m in ipairs(g.members) do if m.owner == self.me then mine = m end end
      if mine then
        local partners = math.max(g.count - 1, 0)
        local text
        if ev.user_id == self.me then
          text = self.tr("note_death_own", { mon = common.mon_name(mon), n = partners })
        else
          text = self.tr("note_death_linked", { player = owner.name, mon = common.mon_name(mon), mine = common.mon_name(mine) })
        end
        self:notify({ tone = "important", text = text, actions = {
          { label = self.tr("open_run"), action = "open_run" },
          { label = self.tr("undo_death"), action = "undo_open", value = g.route },
        } })
        self.hud_until = self.fb.clock() + A.HUD_MS
        self.hud_text = self.tr("hud_death", { n = g.number or 0, mon = common.mon_name(mon), count = partners })
      end
      handled = true
    elseif q.tries >= A.NOTICE_TRIES or (mon and not mon.group) then
      handled = true
    end
    if not handled then
      q.tries = q.tries + 1
      keep[#keep + 1] = q
      self.dirty = true
    end
  end
  self.queue = keep
end

-- ---------------------------------------------------------------- rendering

function A:states()
  local states = self.fb.run.states()
  if not self.viewing and self.me and states[self.me] == nil and self.st then states[self.me] = self.st end
  return states
end

function A:ctx(view)
  return { view = view, run = self.run, me = self.me, ui = self.ui, tr = self.tr, readonly = not self:writable(),
           events = self.events, hud_death = self.hud_until and self.hud_text or nil }
end

function A:render()
  local fb = self.fb
  self.dirty = false
  local now = fb.clock()
  self.last_render = now
  self.run = fb.run.current()
  local cfg = rules.parse(self.run)
  local view = view_mod.view(self.run, self:states(), self.events, cfg)
  self.view = view
  self:process_queue(view)
  local ctx = self:ctx(view)
  if self.viewing then
    -- read-only run section of the Runs screen: the run screen without correction forms or actions
    self.sync:push("run", screen.build(ctx))
    return
  end
  self.sync:push("panel", panel.build(ctx))
  self.sync:push("hud", hud.build(ctx))
  self.sync:push("screen", screen.build(ctx))

  local matched = tile.match(self.tiles, view)
  local live = {}
  for id, p in pairs(matched) do
    local slot = "tile:" .. id
    live[slot] = true
    self.sync:push(slot, tile.build(self.tr, p))
  end
  for slot in pairs(self.tile_slots) do
    if not live[slot] then self.sync:clear(slot) end
  end
  self.tile_slots = live

  if self:writable() then
    local tree = board.build(ctx)
    local enc = util.encode(tree)
    if enc == self.last_board_enc then
      self.board_due = false
    elseif now - self.last_board >= A.BOARD_MS then
      self.board_due = false
      self.last_board = now
      if fb.run.setBoard(tree) then self.last_board_enc = enc end
    else
      self.board_due = true
    end
  end
end

-- ---------------------------------------------------------------- corrections

function A:correction_text(spec)
  local p, tr = spec.payload, self.tr
  local mon
  local owner = self.view and p.user and common.player(self.view, p.user)
  if owner and p.mon and owner.mons[p.mon] then mon = common.mon_name(owner.mons[p.mon]) end
  if p.kind == "add" then mon = common.mon_name({ nickname = p.nickname, species = p.species }) end
  return util.clean_text(tr("ev_c_" .. p.kind, {
    player = self:player_name(self.me), target = p.user and self:player_name(p.user) or "",
    route = p.route and oras.label(p.route, tr) or (p.group and p.group ~= "none" and oras.label(p.group, tr)) or "",
    mon = mon or "?", seq = p.target or "", reason = p.reason or "",
  }), 280)
end

--- Post a manual correction event. Returns true when it was accepted.
function A:post_correction(spec)
  if not self:writable() then return false end
  local ok_valid = corrections.validate_spec(spec)
  if not ok_valid then return false end
  spec.text = self:correction_text(spec)
  local ok, id = pcall(self.fb.run.event, spec)
  if not ok or id == nil then return false end
  self.dirty = true
  return true
end

local function my_player(self) return self.view and common.player(self.view, self.me) end

function A:open_corr(corr)
  corr.user = corr.user or self.me
  self.ui.corr = corr
  self.dirty = true
end

local function field_value(field, value)
  if field == "species" or field == "level" then
    local n = tonumber(value)
    return n and math.tointeger(n) or nil
  elseif field == "gift" then
    return value == true
  end
  if type(value) == "string" then return util.clean_text(value, 280) or "" end
  return value
end

function A:set_place(input)
  if not self:writable() then return end
  local st, fact = detect.set_place(self.st, input)
  self:commit(st, { fact })
end

-- ---------------------------------------------------------------- actions

function A:on_action(action, value, slot)
  if slot == "hotkey" then
    if action == "toggle-hud" then return end -- the host shows or hides the widget
    if action == "open-run" then action = "open_run"
    elseif action == "doesnt-count" then action, value = "dc_open", nil
    else return end
  end
  if not self.run then return end
  local me = my_player(self)
  local writable = self:writable()

  if action == "open_run" then
    self.ui.screen_tab = 1
    self.ui.corr = self.ui.corr
    self.dirty = true
  elseif action == "grave_toggle" then self.ui.grave_open = not self.ui.grave_open; self.dirty = true
  elseif action == "hud_toggle" then self.ui.hud_expanded = not self.ui.hud_expanded; self.dirty = true
  elseif action == "tab" then
    if math.type(value) == "integer" then self.ui.screen_tab = value; self.dirty = true end
  elseif action:sub(1, 3) == "rf:" then self.ui.routes_filter = action:sub(4); self.dirty = true
  elseif action:sub(1, 3) == "lf:" then self.ui.log_filter = action:sub(4); self.dirty = true
  elseif action == "route_select" then self.ui.selected_route = value; self.dirty = true
  elseif action == "map_select" then
    if type(value) == "table" then
      if value.kind == "route" then self.ui.selected_route = value.id
      elseif value.kind == "filter" then self.ui.map_filter = value.value end
      self.dirty = true
    end
  elseif not writable then
    return
  elseif action == "place_select" then
    if type(value) == "string" then self:set_place(value) end
  elseif action == "place_text" then
    self:set_place(type(value) == "string" and value or "")
  elseif action == "badges_select" then
    if math.type(value) == "integer" and value >= 0 and value <= 8 then
      local st = util.copy(self.st)
      st.badges = value
      self:commit(st, {})
    end
  elseif action == "mark_dead" then
    if type(value) == "string" then
      self:post_correction(corrections.mark_dead({ user = self.me, mon = value }))
    end
  elseif action == "dc_open" then
    local route = value or (me and me.place.key)
    if route then
      local corr = { kind = "doesnt_count", route = route, reason = "wrong" }
      local row = common.row_of(self.view, route)
      local cell = row and row.cells[self.me]
      if cell and cell.mon then corr.mon = cell.mon end
      self:open_corr(corr)
    end
  elseif action == "missed_open" then
    if type(value) == "string" then self:open_corr({ kind = "mark_missed", route = value }) end
  elseif action == "undo_open" then
    local g = type(value) == "string" and common.groups(self.view)[value]
    if g then
      self:open_corr({ kind = "undo_death", group = g.route, number = g.number, members = g.members,
        undone = corrections.undo_entries(g) })
    end
  elseif action == "group_open" then
    local m = me and me.mons[value]
    if m then self:open_corr({ kind = "set_group", mon = m.id, group = m.group or "none" }) end
  elseif action == "gift_open" then
    if me and me.mons[value] then self:open_corr({ kind = "set_gift", mon = value, gift = true }) end
  elseif action == "dead_open" then
    if me and me.mons[value] then self:open_corr({ kind = "mark_dead", mon = value }) end
  elseif action == "add_open" then
    self:open_corr({ kind = "add", route = me and me.place.key and oras.is_key(me.place.key) and me.place.key or oras.ROUTE_KEYS[1],
      state = "box" })
  elseif action == "revert_open" then
    if math.type(value) == "integer" then self:open_corr({ kind = "revert", target = value }) end
  elseif action:sub(1, 3) == "cf:" then
    local corr = self.ui.corr
    if corr then
      local field = action:sub(4)
      corr[field] = field_value(field, value)
      corr.error = nil
      self.dirty = true
    end
  elseif action == "corr_cancel" then
    self.ui.corr = nil; self.dirty = true
  elseif action == "corr_submit" then
    local corr = self.ui.corr
    if corr then
      local spec, err = corr_ui.to_spec(corr)
      if not spec then
        corr.error = err
      elseif self:post_correction(spec) then
        self.ui.corr = nil
      else
        corr.error = "c_err_post"
      end
      self.dirty = true
    end
  end
end

return A

end
__mod["app.sync"] = function(...)
-- Keeps fb.ui slots up to date: nothing when the tree is unchanged, fb.ui.patch when only props of
-- blocks with an id changed (same structure), fb.ui.set otherwise.
local util = require("model.util")

local S = {}
S.__index = S

S.MAX_PATCHES = 12

function S.new(fb) return setmetatable({ fb = fb, last = {}, sets = 0, patches = 0 }, S) end

local function diff(old, new, patches)
  if old.type ~= new.type or old.id ~= new.id then return false end
  local oc, nc = old.children or {}, new.children or {}
  if #oc ~= #nc then return false end
  local changed
  for k, v in pairs(new) do
    if k ~= "type" and k ~= "id" and k ~= "children" and util.encode(v) ~= util.encode(old[k]) then
      changed = changed or {}
      changed[k] = v
    end
  end
  for k in pairs(old) do
    if k ~= "type" and k ~= "id" and k ~= "children" and new[k] == nil then return false end -- patch cannot remove
  end
  if changed then
    if not new.id then return false end
    patches[#patches + 1] = { id = new.id, props = changed }
  end
  for i = 1, #nc do
    if not diff(oc[i], nc[i], patches) then return false end
  end
  return true
end

--- Show `tree` in `slot`. Returns "same", "patch" or "set".
function S:push(slot, tree)
  local old = self.last[slot]
  if old then
    if util.encode(old) == util.encode(tree) then return "same" end
    local patches = {}
    if diff(old, tree, patches) and #patches <= S.MAX_PATCHES then
      for _, p in ipairs(patches) do self.fb.ui.patch(slot, p.id, p.props) end
      self.last[slot] = util.copy(tree)
      self.patches = self.patches + #patches
      return "patch"
    end
  end
  self.fb.ui.set(slot, tree)
  self.last[slot] = util.copy(tree)
  self.sets = self.sets + 1
  return "set"
end

function S:clear(slot)
  if self.last[slot] then
    self.fb.ui.clear(slot)
    self.last[slot] = nil
  end
end

return S

end
__mod["data.oras"] = function(...)
-- Route keys and small data tables for Omega Ruby / Alpha Sapphire.
-- Keyed by internal route keys only; names (routes, species, places) are never shipped here.
local util = require("model.util")

local M = {}

M.STARTER = "starter"
M.FIRST_ROUTE = 101
M.LAST_ROUTE = 134

--- Ordered route keys "route-101" .. "route-134".
M.ROUTE_KEYS = {}
for n = M.FIRST_ROUTE, M.LAST_ROUTE do
  M.ROUTE_KEYS[#M.ROUTE_KEYS + 1] = "route-" .. n
end

--- zone id -> route key (string) or false (known zone that is not a route, e.g. a town).
--- EMPTY on purpose: filled once pokemon-core reports ORAS locations (location() is not
--- implemented there yet). Until then the place comes from manual input.
M.ZONE_TO_ROUTE = {}

--- Route key -> { x, y, area? } on the region map image (image coordinates). EMPTY on purpose:
--- the map image and its coordinates are read from the player's own game file at runtime, which is
--- not implemented yet. While empty, the screen hides the Map tab.
M.COORDS = {}
M.MAP_SIZE = nil -- { w, h } of the map image once known

--- Level cap hint by number of badges owned: LEVEL_CAPS[badges] = cap of the next gym.
--- VERIFY LOCALLY against the real game before relying on it; hints only, never blocking.
M.LEVEL_CAPS = { [0] = 15, 19, 24, 29, 31, 33, 42, 43 }

--- Route key -> { x, y, area? } on the region map image (image coordinates). EMPTY on purpose:
--- the map image and its coordinates are read from the player's own game file at runtime, which is
--- not implemented yet. While empty, the screen hides the Map tab.
M.COORDS = {}
M.MAP_SIZE = nil -- { w, h } of the map image once known

--- Level cap hint for `badges` badges, or nil when unknown (for example all eight badges).
function M.level_cap(badges)
  if math.type(badges) ~= "integer" then return nil end
  return M.LEVEL_CAPS[badges]
end

--- Route number of a key "route-NNN", or nil.
function M.route_number(key)
  local n = type(key) == "string" and key:match("^route%-(%d+)$")
  n = n and tonumber(n)
  if n and n >= M.FIRST_ROUTE and n <= M.LAST_ROUTE then return n end
  return nil
end

--- True for "starter", a known route key or a free "place:<text>" key.
function M.is_key(key)
  if type(key) ~= "string" then return false end
  if key == M.STARTER or M.route_number(key) then return true end
  local text = key:match("^place:(.+)$")
  return text ~= nil and util.clean_text(text, 48) == text
end

--- Free place key for text typed by the user ("place:<text>", text kept as typed apart from
--- whitespace cleanup, at most 48 characters). nil for empty text.
function M.custom_key(text)
  local t = util.clean_text(text, 48)
  return t and ("place:" .. t) or nil
end

--- Sort index: starter first, routes in numeric order, free places after (by text).
function M.order_index(key)
  if key == M.STARTER then return 0 end
  local n = M.route_number(key)
  if n then return n - M.FIRST_ROUTE + 1 end
  return 1000
end

--- Comparison function for route keys.
function M.compare(a, b)
  local ia, ib = M.order_index(a), M.order_index(b)
  if ia ~= ib then return ia < ib end
  return tostring(a) < tostring(b)
end

--- Display text. `tr` is fb.i18n.t (key, vars); free places keep the text as typed.
function M.label(key, tr)
  if key == M.STARTER then return tr("route_starter") end
  local n = M.route_number(key)
  if n then return tr("route", { n = n }) end
  local text = type(key) == "string" and key:match("^place:(.+)$")
  return text or tostring(key)
end

return M

end
__mod["main"] = function(...)
-- Entry module of the SoulLink & Nuzlocke plugin: wires the run model to the Player.
local controller = require("app.controller")

fb.log.info(fb.i18n.t("loaded", { version = (fb.plugin and fb.plugin.version) or "?" }))
local app = controller.new(fb)
app:start()

end
__mod["model.corrections"] = function(...)
-- Manual corrections: run events of type "soullink.correction" with source "manual".
-- Corrections are applied by model/view.lua in seq order on top of the own states; they never
-- rewrite the own state. Builders return a spec { type, source = "manual", payload }; the caller
-- adds `text` and posts it with fb.run.event.
--
-- payload.user is the player the correction is about (the author is the event's user_id).
local util = require("model.util")
local oras = require("data.oras")

local C = {}

C.TYPE = "soullink.correction"
C.MAX_PAYLOAD = 4096
C.KINDS = {
  "doesnt_count", "undo_death", "set_group", "add", "mark_missed", "mark_dead", "set_gift", "revert",
}
C.REASONS = { dupe = true, shiny = true, wrong = true }
C.ADD_STATES = { team = true, box = true, dead = true }

local function spec(payload)
  return { type = C.TYPE, source = "manual", payload = payload }
end

--- "This encounter/catch doesn't count". `route` and/or `mon`; `reason` = dupe|shiny|wrong.
--- Without `mon`: reopens an encounter/missed route (or excludes the route's counted mon).
--- With `mon`: that mon stops counting and its route reopens.
function C.doesnt_count(a)
  return spec({ kind = "doesnt_count", user = a.user, route = a.route, mon = a.mon, reason = a.reason })
end

--- Undo the death of a whole link group. `group` = route key; `undone` = list of
--- { owner = user id, mon = mon id, deaths = death count that is undone } (use C.undo_entries).
function C.undo_death(a)
  return spec({ kind = "undo_death", group = a.group, reason = a.reason, undone = a.undone })
end

--- Build the `undone` list from a view group (member list as produced by view.view).
function C.undo_entries(group)
  local out = {}
  for _, m in ipairs(group.members or {}) do
    out[#out + 1] = { owner = m.owner, mon = m.id, deaths = m.deaths }
  end
  return out
end

--- Move a mon to the link group of `group` (route key) or to no group ("none").
function C.set_group(a)
  return spec({ kind = "set_group", user = a.user, mon = a.mon, group = a.group })
end

--- Hand-added mon. state = team|box|dead. Replaces "missed"/open on the route.
function C.add(a)
  return spec({ kind = "add", user = a.user, route = a.route, species = a.species, form = a.form,
                nickname = a.nickname, level = a.level, state = a.state or "box", shiny = a.shiny })
end

function C.mark_missed(a) return spec({ kind = "mark_missed", user = a.user, route = a.route }) end

function C.mark_dead(a) return spec({ kind = "mark_dead", user = a.user, mon = a.mon, reason = a.reason }) end

--- Mark (or unmark with gift = false) a mon as a gift: no link group.
function C.set_gift(a)
  local g = a.gift
  if g == nil then g = true end
  return spec({ kind = "set_gift", user = a.user, mon = a.mon, gift = g })
end

--- Revert the correction event with seq `target`.
function C.revert(a) return spec({ kind = "revert", target = a.target, reason = a.reason }) end

local function is_str(v, max) return type(v) == "string" and #v > 0 and #v <= (max or 64) end
local function is_route_ref(v) return type(v) == "string" and oras.is_key(v) end
local function opt(v, f) return v == nil or f(v) end
local function is_int(v) return math.type(v) == "integer" end

local checks = {
  doesnt_count = function(p)
    return is_str(p.user) and (p.route ~= nil or p.mon ~= nil) and opt(p.route, is_route_ref)
      and opt(p.mon, is_str) and opt(p.reason, function(r) return C.REASONS[r] == true end)
  end,
  undo_death = function(p)
    if not is_route_ref(p.group) or type(p.undone) ~= "table" or #p.undone == 0 then return false end
    for _, e in ipairs(p.undone) do
      if type(e) ~= "table" or not is_str(e.owner) or not is_str(e.mon) or not is_int(e.deaths) or e.deaths < 0 then
        return false
      end
    end
    return true
  end,
  set_group = function(p)
    return is_str(p.user) and is_str(p.mon) and (p.group == "none" or is_route_ref(p.group))
  end,
  add = function(p)
    return is_str(p.user) and is_route_ref(p.route) and is_int(p.species) and p.species > 0
      and C.ADD_STATES[p.state] == true and opt(p.level, is_int)
      and opt(p.nickname, function(n) return is_str(n, 48) end) and opt(p.form, is_int)
  end,
  mark_missed = function(p) return is_str(p.user) and is_route_ref(p.route) end,
  mark_dead = function(p) return is_str(p.user) and is_str(p.mon) end,
  set_gift = function(p) return is_str(p.user) and is_str(p.mon) and type(p.gift) == "boolean" end,
  revert = function(p) return is_int(p.target) and p.target > 0 end,
}

--- Validate a correction payload. Returns true, or false plus a reason string.
function C.validate(payload)
  if type(payload) ~= "table" then return false, "payload is not a table" end
  local check = checks[payload.kind]
  if not check then return false, "unknown kind" end
  if payload.reason ~= nil and type(payload.reason) ~= "string" then return false, "bad reason" end
  if type(payload.reason) == "string" and #payload.reason > 280 then return false, "reason too long" end
  if not check(payload) then return false, "invalid fields for " .. payload.kind end
  if util.json_size(payload) > C.MAX_PAYLOAD then return false, "payload larger than 4 KiB" end
  return true
end

--- Validate a spec returned by a builder (type, source and payload).
function C.validate_spec(s)
  if type(s) ~= "table" or s.type ~= C.TYPE or s.source ~= "manual" then return false, "not a correction spec" end
  return C.validate(s.payload)
end

return C

end
__mod["model.detect"] = function(...)
-- Detection: diff(previous own state, core snapshot, cfg) -> new own state + facts.
-- Pure; never touches fb. Everything the core cannot report (place, battle, hp, encounters)
-- degrades to "unknown": nothing is invented, the UI/user supplies it through manual input.
local util = require("model.util")
local rules = require("model.rules")
local state = require("model.state")
local oras = require("data.oras")

local D = {}

-- Snapshot (what the caller passes; model/snapshot.lua builds it from pokemon.core):
--   team     list of generic records, or nil = unknown
--   boxes    list of boxes (each a list of records) or a flat list of records, or nil = unknown
--   location { zone = number?, name = string? }   or nil
--   battle   { active = bool, wild = bool, horde = bool?, foes = {records} }  or nil
--   encounters list of { species, form?, shiny?, horde? } newly seen encounters, or nil
--   badges   number | { count = n } | list of booleans
-- Facts (kind): place, catch, evolve, death, moved, encounter, missed. See docs/architecture.md.

local function default_family(species) return species end

local function collect(snap)
  local list, map = {}, {}
  local team_known = type(snap.team) == "table"
  local boxes_known = type(snap.boxes) == "table"
  local function add(rec, where)
    if type(rec) ~= "table" or type(rec.species) ~= "number" then return end
    local pid = util.hex8(rec.personality)
    if not pid or map[pid] then return end
    local c = { pid = pid, rec = rec, where = where }
    map[pid] = c
    list[#list + 1] = c
  end
  if team_known then for _, rec in ipairs(snap.team) do add(rec, "team") end end
  if boxes_known then
    for _, box in ipairs(snap.boxes) do
      if type(box) == "table" and box.personality ~= nil then
        add(box, "box")
      elseif type(box) == "table" then
        for _, rec in ipairs(box) do add(rec, "box") end
      end
    end
  end
  return list, map, team_known, boxes_known
end

local function badge_count(b)
  if math.type(b) == "integer" then return b end
  if type(b) ~= "table" then return nil end
  if math.type(b.count) == "integer" then return b.count end
  local n = 0
  for _, v in ipairs(b) do if v == true then n = n + 1 end end
  return n
end

local function battle_info(snap)
  local b = snap.battle
  if type(b) ~= "table" or type(b.active) ~= "boolean" then return { known = false } end
  return { known = true, active = b.active, wild = b.wild == true, horde = b.horde == true,
           foes = type(b.foes) == "table" and b.foes or (type(b.foe) == "table" and { b.foe } or {}) }
end

-- Is a line (family) already owned by a tracked mon that counts for the dupes clause?
local function owns_line(st, species, family)
  if species == nil then return false end
  local fam = family(species)
  for _, m in pairs(st.mons) do
    if m.why ~= "dupe" and m.why ~= "extra" and m.where ~= "gone" and family(m.species) == fam then
      return true
    end
  end
  return false
end

local function update_place(st, loc, facts, zones)
  if type(loc) ~= "table" or loc.zone == nil then return end
  local old = st.place or { manual = false }
  local mapped = zones[loc.zone]
  local new
  if mapped ~= nil then
    new = { key = mapped or nil, name = loc.name, zone = loc.zone, manual = false }
  elseif old.manual then
    return -- unknown zone: keep what the user set by hand
  else
    new = { name = loc.name, zone = loc.zone, manual = false }
  end
  if new.key ~= old.key or new.name ~= old.name or new.zone ~= old.zone or old.manual then
    st.place = new
    if new.key ~= old.key or new.name ~= old.name then
      facts[#facts + 1] = { kind = "place", key = new.key, name = new.name, zone = new.zone,
                            manual = false, previous = old.key }
    end
  end
end

--- Set the place by hand. `input` is a route key ("route-104", "starter", "place:<text>") or free
--- text typed by the user (becomes "place:<text>"); nil/"" clears the place. `name` is optional
--- display text. Returns the new state and a place fact (or nil when nothing changed).
function D.set_place(prev, input, name)
  local st = state.ensure(util.copy(prev))
  local old = st.place or { manual = false }
  local key
  if input ~= nil and input ~= "" then
    key = oras.is_key(input) and input or oras.custom_key(input)
  end
  st.place = { key = key, name = name, manual = true }
  if key == old.key and name == old.name and old.manual then return st, nil end
  return st, { kind = "place", key = key, name = name, manual = true, previous = old.key }
end

local function handle_encounter(st, cfg, pk, foe, horde, facts, family)
  local fact = { kind = "encounter", route = pk, species = foe.species, form = foe.form,
                 shiny = foe.shiny == true, horde = horde, counts = false }
  local r = cfg.rules
  local existing = pk and st.routes[pk]
  if horde and not r.hordes_count then
    fact.why = "horde"
  elseif pk == nil then
    fact.why = "no_place"
  elseif fact.shiny and r.shiny_clause then
    fact.why = "shiny"
  elseif r.dupes_clause and owns_line(st, foe.species, family) then
    fact.why = "dupe"
  elseif existing and r.first_encounter_only then
    fact.why = "used"
  else
    fact.counts = true
    if not existing then
      st.routes[pk] = { status = "encounter", species = foe.species, kind = horde and "horde" or "wild" }
    end
  end
  facts[#facts + 1] = fact
end

local function handle_catch(st, cfg, c, pk, starter, facts, family)
  local rec, r = c.rec, cfg.rules
  local dupe = r.dupes_clause and owns_line(st, rec.species, family) -- before the mon is added
  local mon = {
    species = rec.species, form = rec.form, nickname = util.clean_text(rec.nickname, 24),
    level = rec.level, shiny = rec.shiny == true or nil, route = pk, where = c.where,
    hp = type(rec.hp) == "number" and rec.hp or nil,
    mhp = type(rec.max_hp) == "number" and rec.max_hp or nil,
  }
  if rec.nicknamed == false then mon.nicknamed = false end
  st.mons[c.pid] = mon
  local fact = { kind = "catch", mon = c.pid, species = rec.species, form = rec.form,
                 nickname = mon.nickname, level = rec.level, shiny = rec.shiny == true,
                 route = pk, where = c.where, counts = false, starter = starter or nil }
  local existing = pk and st.routes[pk]
  if rec.egg then
    mon.gift, mon.why = true, "gift"
    fact.gift, fact.why = true, "gift"
  elseif pk == nil then
    fact.why = "no_place"
  elseif mon.shiny and r.shiny_clause then
    mon.why, fact.why = "shiny", "shiny"
  elseif dupe then
    mon.why, fact.why = "dupe", "dupe"
  else
    local entry = { status = "caught", mon = c.pid, species = rec.species,
                    kind = starter and "starter" or "wild" }
    if not existing or existing.status == "encounter" then
      st.routes[pk], fact.counts = entry, true
    elseif existing.status == "missed" and existing.species == rec.species then
      st.routes[pk], fact.counts = entry, true -- the catch arrived after the battle was closed
    elseif not r.first_encounter_only then
      mon.why, fact.why = "additional", "additional"
    else
      mon.why, fact.why = "extra", "extra"
    end
  end
  facts[#facts + 1] = fact
end

--- diff(prev, snap, cfg, opts) -> new_state, facts
---   prev  own state (nil = fresh); never modified
---   snap  see the snapshot description above
---   cfg   result of rules.parse (or flat rule flags)
---   opts  { family = function(species) -> family id (default: species itself),
---           zones = zone -> route key table (default data.oras.ZONE_TO_ROUTE),
---           first = "auto"|"baseline"|"starter" (what the first complete snapshot means),
---           game = { id, language } }
--- Tracking starts with the first snapshot where team and boxes are both known: then either
--- everything present is baseline, or (first = "starter", or "auto" with exactly one mon in the
--- team and no box mon) that mon is the starter caught on route "starter".
function D.diff(prev, snap, cfg, opts)
  opts = opts or {}
  cfg = rules.normalize(cfg)
  local st = state.ensure(util.copy(prev))
  snap = type(snap) == "table" and snap or {}
  local facts = {}
  local family = opts.family or default_family
  if type(opts.game) == "table" then
    st.game.id = st.game.id or opts.game.id
    st.game.language = st.game.language or opts.game.language
  end

  update_place(st, snap.location, facts, opts.zones or oras.ZONE_TO_ROUTE)
  local b = badge_count(snap.badges)
  if b then st.badges = b end

  local list, map, team_known, boxes_known = collect(snap)
  local bat = battle_info(snap)
  local catch_place

  if not st.started then
    if not (team_known and boxes_known) then return st, facts end
    local first = opts.first or "auto"
    local starter = first == "starter"
      or (first == "auto" and #list == 1 and list[1].where == "team" and not list[1].rec.egg)
    st.started = true
    if not starter then
      for _, c in ipairs(list) do st.baseline[c.pid] = true end
      st.inb = bat.known and bat.active or false
      return st, facts
    end
    catch_place = oras.STARTER
  end

  -- known mons: updates, moves, evolution, deaths, disappearance
  for _, pid in ipairs(util.keys(st.mons)) do
    local m, c = st.mons[pid], map[pid]
    if c then
      local rec = c.rec
      m.miss = nil
      if m.species ~= rec.species then
        facts[#facts + 1] = { kind = "evolve", mon = pid, from = m.species, to = rec.species,
                              nickname = m.nickname, route = m.route }
        m.species = rec.species
      end
      m.form = rec.form
      m.level = rec.level or m.level
      m.nickname = util.clean_text(rec.nickname, 24) or m.nickname
      if rec.nicknamed == false then m.nicknamed = false elseif rec.nicknamed == true then m.nicknamed = nil end
      if rec.shiny == true then m.shiny = true end
      if m.where ~= c.where then
        facts[#facts + 1] = { kind = "moved", mon = pid, from = m.where, to = c.where }
        m.where = c.where
      end
      if type(rec.hp) == "number" then
        if m.hp and m.hp > 0 and rec.hp <= 0 then
          m.deaths = (m.deaths or 0) + 1
          facts[#facts + 1] = { kind = "death", mon = pid, species = m.species, nickname = m.nickname,
                                route = m.route, deaths = m.deaths }
        end
        m.hp = rec.hp
      end
      if type(rec.max_hp) == "number" then m.mhp = rec.max_hp end
    elseif team_known and boxes_known and m.where ~= "gone" then
      m.miss = (m.miss or 0) + 1 -- gone only after two snapshots in a row (no transient states)
      if m.miss >= 2 then
        facts[#facts + 1] = { kind = "moved", mon = pid, from = m.where, to = "gone" }
        m.where, m.miss = "gone", nil
      end
    end
  end

  -- new mons
  for _, c in ipairs(list) do
    if not st.baseline[c.pid] and not st.mons[c.pid] then
      handle_catch(st, cfg, c, catch_place or st.place.key, catch_place ~= nil, facts, family)
    end
  end

  -- team order (tracked mons only)
  if team_known then
    st.order = {}
    for _, c in ipairs(list) do
      if c.where == "team" and st.mons[c.pid] then st.order[#st.order + 1] = c.pid end
    end
  end

  -- encounters and missed routes
  if bat.known then
    if bat.active and not st.inb and bat.wild then
      handle_encounter(st, cfg, st.place.key, bat.foes[1] or {}, bat.horde, facts, family)
    elseif not bat.active and st.inb then
      for _, key in ipairs(util.keys(st.routes)) do
        local e = st.routes[key]
        if e.status == "encounter" then
          e.status = "missed"
          facts[#facts + 1] = { kind = "missed", route = key, species = e.species }
        end
      end
    end
    st.inb = bat.active
  elseif type(snap.encounters) == "table" then
    for _, e in ipairs(snap.encounters) do
      if type(e) == "table" then
        handle_encounter(st, cfg, st.place.key, e, e.horde == true, facts, family)
      end
    end
  end

  return st, facts
end

return D

end
__mod["model.events"] = function(...)
-- Payload builders for the automatic run events. Posting (fb.run.event) is done by the caller.
-- Builders return a spec { type =, payload =, source = "automatic" }; `text` (at most 280
-- characters, translated, with names read from the game) is added by the caller.
local util = require("model.util")

local E = {}

E.TYPES = {
  catch = "soullink.catch",
  death = "soullink.death",
  encounter = "soullink.encounter",
  place = "soullink.place",
  correction = "soullink.correction",
}
E.MAX_PAYLOAD = 4096

local function put(t, k, v) if v ~= nil then t[k] = v end end

--- Build the event spec for a detection fact, or nil for facts without an event
--- (evolve, moved). `user` is the user id of the own participant.
---   catch     payload { user, mon, species, form?, nickname?, level?, shiny?, route?, counts, why?, gift?, starter?, where }
---   death     payload { user, mon, species, nickname?, route?, deaths }
---   encounter payload { user, outcome = "seen"|"missed", route?, species?, form?, shiny?, horde?, counts, why? }
---   place     payload { user, route?, name?, manual }
function E.from_fact(fact, user)
  local k = fact.kind
  local p = { user = user }
  if k == "catch" then
    p.mon, p.species, p.counts, p.where = fact.mon, fact.species, fact.counts, fact.where
    put(p, "form", fact.form); put(p, "nickname", fact.nickname); put(p, "level", fact.level)
    put(p, "route", fact.route); put(p, "why", fact.why)
    if fact.shiny then p.shiny = true end
    if fact.gift then p.gift = true end
    if fact.starter then p.starter = true end
    return { type = E.TYPES.catch, payload = p, source = "automatic" }
  elseif k == "death" then
    p.mon, p.species, p.deaths = fact.mon, fact.species, fact.deaths
    put(p, "nickname", fact.nickname); put(p, "route", fact.route)
    return { type = E.TYPES.death, payload = p, source = "automatic" }
  elseif k == "encounter" or k == "missed" then
    p.outcome = k == "missed" and "missed" or "seen"
    if k == "missed" then p.counts = false else p.counts = fact.counts end
    put(p, "route", fact.route); put(p, "species", fact.species)
    if k == "encounter" then
      put(p, "form", fact.form); put(p, "why", fact.why)
      if fact.shiny then p.shiny = true end
      if fact.horde then p.horde = true end
    end
    return { type = E.TYPES.encounter, payload = p, source = "automatic" }
  elseif k == "place" then
    put(p, "route", fact.key); put(p, "name", fact.name)
    p.manual = fact.manual == true
    return { type = E.TYPES.place, payload = p, source = "automatic" }
  end
  return nil
end

--- All specs for a list of facts, in order.
function E.from_facts(facts, user)
  local out = {}
  for _, f in ipairs(facts) do
    local s = E.from_fact(f, user)
    if s then out[#out + 1] = s end
  end
  return out
end

--- True when the payload fits the platform limit (4 KiB).
function E.fits(payload) return util.json_size(payload) <= E.MAX_PAYLOAD end

return E

end
__mod["model.rules"] = function(...)
-- Run rules: defaults and parsing of the run settings.
-- Settings live in the run settings under the plugin id:
--   run.settings["net.framebeam.soullink"] = { mode = "soullink", rules = { dupes_clause = false, ... } }
local R = {}

R.PLUGIN_ID = "net.framebeam.soullink"
R.MODES = { nuzlocke = true, soullink = true }

--- Default rule switches (all are booleans).
R.DEFAULTS = {
  first_encounter_only = true,
  dupes_clause = true,
  shiny_clause = true,
  hordes_count = false,
  pairs_differ_primary_type = false,
  only_linked_in_team = false,
  nickname_required = true,
  level_caps = true,
}

--- Rule keys in a fixed order (for UI lists).
R.ORDER = {
  "first_encounter_only", "dupes_clause", "shiny_clause", "hordes_count",
  "pairs_differ_primary_type", "only_linked_in_team", "nickname_required", "level_caps",
}

--- Fresh copy of the default rules.
function R.defaults()
  local t = {}
  for k, v in pairs(R.DEFAULTS) do t[k] = v end
  return t
end

--- Number of participants with status "joined" (a missing status counts as joined).
function R.joined_count(run)
  local n = 0
  for _, p in ipairs(type(run) == "table" and run.participants or {}) do
    if type(p) == "table" and (p.status == nil or p.status == "joined") then n = n + 1 end
  end
  return n
end

--- Parse the rules of a run (`fb.run.current()` result, may be nil).
--- Returns cfg = { mode = "nuzlocke"|"soullink", mode_set = bool, rules = {<flag> = bool} }.
--- Unknown keys are ignored, wrong types fall back to the defaults. Without a valid mode:
--- "soullink" with two or more joined participants, otherwise "nuzlocke".
function R.parse(run)
  local mine
  if type(run) == "table" and type(run.settings) == "table" then
    mine = run.settings[R.PLUGIN_ID]
  end
  if type(mine) ~= "table" then mine = {} end
  local cfg = { rules = R.defaults(), mode_set = false }
  if type(mine.mode) == "string" and R.MODES[mine.mode] then
    cfg.mode, cfg.mode_set = mine.mode, true
  else
    cfg.mode = R.joined_count(run) >= 2 and "soullink" or "nuzlocke"
  end
  if type(mine.rules) == "table" then
    for k, default in pairs(R.DEFAULTS) do
      local v = mine.rules[k]
      if type(v) == type(default) then cfg.rules[k] = v end
    end
  end
  return cfg
end

--- Accepts a cfg from parse(), a flat table of rule flags or nil; returns a complete cfg.
function R.normalize(x)
  if type(x) == "table" and type(x.rules) == "table" and R.MODES[x.mode] then
    local cfg = { mode = x.mode, mode_set = x.mode_set == true, rules = R.defaults() }
    for k, default in pairs(R.DEFAULTS) do
      if type(x.rules[k]) == type(default) then cfg.rules[k] = x.rules[k] end
    end
    return cfg
  end
  local cfg = { mode = "nuzlocke", mode_set = false, rules = R.defaults() }
  if type(x) == "table" then
    if type(x.mode) == "string" and R.MODES[x.mode] then cfg.mode, cfg.mode_set = x.mode, true end
    local flat = type(x.rules) == "table" and x.rules or x
    for k, default in pairs(R.DEFAULTS) do
      if type(flat[k]) == type(default) then cfg.rules[k] = flat[k] end
    end
  end
  return cfg
end

--- Settings table to store in the run settings for `cfg` (what a run creator writes).
function R.to_settings(cfg)
  cfg = R.normalize(cfg)
  local rules = {}
  for k, v in pairs(cfg.rules) do rules[k] = v end
  return { [R.PLUGIN_ID] = { mode = cfg.mode, rules = rules } }
end

return R

end
__mod["model.snapshot"] = function(...)
-- Builds the detection snapshot from the `pokemon.core` interface.
-- Every method may be missing (nil, "unsupported") or not ready (nil, "not_ready"); a missing
-- part stays nil in the snapshot ("unknown"), which detect.diff handles without inventing data.
local P = {}

P.INTERFACE = "pokemon.core"

--- collect(call) -> snapshot, issues
---   call(fn, ...) returns what pokemon.core's `fn` returns (see from_core). Errors are caught.
---   issues = { team = reason?, boxes = reason?, location = ..., battle = ..., encounters = ..., badges = ... }
--- opts.skip_boxes: do not read the boxes, use opts.boxes (the last complete read) instead.
--- Box numbers run 1..box_count() (assumption; the core documents box(n) without a base: open).
function P.collect(call, opts)
  opts = opts or {}
  local snap, issues = {}, {}
  local function ask(fn, ...)
    local ok, a, b = pcall(call, fn, ...)
    if not ok then return nil, "error" end
    return a, b
  end
  local function part(name, fn, ...)
    local v, why = ask(fn, ...)
    if type(v) == "table" or (name == "badges" and type(v) == "number") then
      snap[name] = v
    else
      issues[name] = why or "unavailable"
    end
  end

  part("team", "team")
  local n, why
  if opts.skip_boxes then
    snap.boxes = opts.boxes
    if not opts.boxes then issues.boxes = "not_ready" end
    n = -1
  else
    n, why = ask("box_count")
  end
  if n == -1 then
    -- boxes taken from the cache above
  elseif math.type(n) == "integer" and n >= 0 then
    local boxes, complete = {}, true
    for i = 1, n do
      local box = ask("box", i)
      if type(box) == "table" then boxes[i] = box else complete = false; issues.boxes = "not_ready"; break end
    end
    if complete then snap.boxes = boxes end
  else
    issues.boxes = why or "unavailable"
  end
  part("location", "location")
  part("battle", "battle")
  part("encounters", "encounters")
  part("badges", "badges")
  return snap, issues
end

--- Snapshot from the live core: fb.call("pokemon.core", fn, ...).
function P.from_core(fb, opts)
  return P.collect(function(fn, ...) return fb.call(P.INTERFACE, fn, ...) end, opts)
end

return P

end
__mod["model.state"] = function(...)
-- Own state: one object per participant, written with fb.run.setState (limit 64 KiB).
local util = require("model.util")

local S = {}

S.VERSION = 1
--- Soft limit well below the 64 KiB platform limit; guard() compacts above it.
S.MAX_BYTES = 48 * 1024

--- Fresh state. `game` = { id = ..., language = ... } (both optional).
---
--- Schema (v = 1), all keys strings, JSON-able:
---   v, started (bool: baseline taken), inb (bool: wild battle was active at the last diff)
---   game   = { id, language }
---   place  = { key?, name?, zone?, manual }   key = route key or nil (no place / not a route)
---   baseline = { ["<hex8 personality>"] = true }   mons present before tracking, ignored forever
---   mons   = { ["<hex8>"] = { species, form?, nickname?, nicknamed? (false only), level, shiny? (true only),
---              route?, where = "team"|"box"|"gone", deaths? (absent = 0), hp?, gift? (true only),
---              why? = "extra"|"dupe"|"shiny"|"additional"|"gift", miss? } }
---   routes = { [route key] = { status = "encounter"|"caught"|"missed", mon?, species?, kind? } }
---   order  = { "<hex8>", ... }   tracked mons in team order
---   badges = number
function S.new(game)
  local g = {}
  if type(game) == "table" then
    g.id = game.id
    g.language = game.language
  end
  return {
    v = S.VERSION, started = false, inb = false,
    game = g, place = { manual = false },
    baseline = {}, mons = {}, routes = {}, order = {}, badges = 0,
  }
end

--- Complete a state received from the Hub (nil or older shape) so the model can use it.
function S.ensure(st)
  if type(st) ~= "table" then return S.new() end
  st.v = st.v or S.VERSION
  st.game = st.game or {}
  st.place = st.place or { manual = false }
  st.baseline = st.baseline or {}
  st.mons = st.mons or {}
  st.routes = st.routes or {}
  st.order = st.order or {}
  st.badges = st.badges or 0
  return st
end

--- Death count of a tracked mon (absent = 0).
function S.deaths(mon) return mon and mon.deaths or 0 end

--- Size in bytes of the JSON encoding of `st`.
function S.size(st) return util.json_size(st) end

--- Drop what can be dropped safely when the state is large: mons that are gone and own no route
--- entry, then shorten nicknames. Returns the (same) state. Baseline entries are never dropped.
function S.compact(st)
  local referenced = {}
  for _, r in pairs(st.routes) do if r.mon then referenced[r.mon] = true end end
  for pid, m in pairs(st.mons) do
    if m.where == "gone" and not referenced[pid] and (m.deaths or 0) == 0 then st.mons[pid] = nil end
  end
  if S.size(st) > S.MAX_BYTES then
    for _, m in pairs(st.mons) do
      if m.nickname then m.nickname = util.clean_text(m.nickname, 12) end
    end
  end
  return st
end

--- Size guard: returns ok, bytes. Compacts when above MAX_BYTES; ok is false when it still is.
function S.guard(st)
  local n = S.size(st)
  if n <= S.MAX_BYTES then return true, n end
  S.compact(st)
  n = S.size(st)
  return n <= S.MAX_BYTES, n
end

return S

end
__mod["model.util"] = function(...)
-- Small pure helpers shared by the model modules.
local U = {}

--- Deep copy of plain data (tables, strings, numbers, booleans).
function U.copy(v)
  if type(v) ~= "table" then return v end
  local c = {}
  for k, x in pairs(v) do c[k] = U.copy(x) end
  return c
end

--- Sorted list of the keys of `t` (strings or numbers; mixed keys sort by string form).
function U.keys(t)
  local out = {}
  for k in pairs(t or {}) do out[#out + 1] = k end
  table.sort(out, function(a, b)
    if type(a) == type(b) and (type(a) == "number" or type(a) == "string") then return a < b end
    return tostring(a) < tostring(b)
  end)
  return out
end

--- Personality value -> 8-hex-digit lowercase string (the key of a Pokemon in the own state).
--- Returns nil when `n` is not an integer value.
function U.hex8(n)
  if math.type(n) == "float" then n = math.tointeger(n) end
  if math.type(n) ~= "integer" then return nil end
  return string.format("%08x", n & 0xffffffff)
end

local ESC = { ['"'] = '\\"', ["\\"] = "\\\\", ["\n"] = "\\n", ["\r"] = "\\r", ["\t"] = "\\t" }

local function enc_string(s)
  return '"' .. s:gsub('[%c"\\]', function(c)
    return ESC[c] or string.format("\\u%04x", c:byte())
  end) .. '"'
end

local function is_array(t)
  local n = 0
  for _ in pairs(t) do n = n + 1 end
  if n == 0 then return false end
  for i = 1, n do if t[i] == nil then return false end end
  return true
end

--- Deterministic JSON encoding (sorted object keys). Used to measure state and payload sizes.
--- Raises on functions and non-finite numbers.
function U.encode(v)
  local tv = type(v)
  if tv == "nil" then return "null" end
  if tv == "boolean" then return tostring(v) end
  if tv == "number" then
    if v ~= v or v == math.huge or v == -math.huge then error("non-finite number") end
    if math.type(v) == "integer" then return tostring(v) end
    return string.format("%.14g", v)
  end
  if tv == "string" then return enc_string(v) end
  if tv ~= "table" then error("cannot encode " .. tv) end
  local out = {}
  if is_array(v) then
    for i = 1, #v do out[i] = U.encode(v[i]) end
    return "[" .. table.concat(out, ",") .. "]"
  end
  for _, k in ipairs(U.keys(v)) do
    out[#out + 1] = enc_string(tostring(k)) .. ":" .. U.encode(v[k])
  end
  return "{" .. table.concat(out, ",") .. "}"
end

--- Size in bytes of the JSON encoding.
function U.json_size(v) return #U.encode(v) end

--- Trim and collapse whitespace; nil for empty.
function U.clean_text(s, max)
  if type(s) ~= "string" then return nil end
  s = s:gsub("%c", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
  if s == "" then return nil end
  if max and utf8.len(s) and utf8.len(s) > max then
    s = s:sub(1, (utf8.offset(s, max + 1) or (#s + 1)) - 1)
  elseif max and #s > max and not utf8.len(s) then
    s = s:sub(1, max)
  end
  return s
end

return U

end
__mod["model.view"] = function(...)
-- Derived run view: everything the UI shows, computed from the participants' own states and the
-- run events. Pure and deterministic: the same inputs give the same table (no clocks, no pairs()
-- order dependence). Nothing is stored; link groups, deaths and numbers are recomputed.
local util = require("model.util")
local rules = require("model.rules")
local state = require("model.state")
local corrections = require("model.corrections")
local events_mod = require("model.events")
local oras = require("data.oras")

local V = {}

local INF = math.huge

local function joined(p) return p.status == nil or p.status == "joined" end
local function mkey(owner, id) return owner .. "\0" .. id end

local function collect_events(events)
  local list = {}
  for _, ev in ipairs(events or {}) do
    if type(ev) == "table" and math.type(ev.seq) == "integer" then list[#list + 1] = ev end
  end
  table.sort(list, function(a, b) return a.seq < b.seq end)
  local catch_seq, death_seq, corr, invalid = {}, {}, {}, {}
  for _, ev in ipairs(list) do
    local p = type(ev.payload) == "table" and ev.payload or {}
    local user = ev.user_id or p.user
    if ev.type == events_mod.TYPES.catch and user and type(p.mon) == "string" then
      local k = mkey(user, p.mon)
      if not catch_seq[k] then catch_seq[k] = ev.seq end
    elseif ev.type == events_mod.TYPES.death and user and type(p.mon) == "string" then
      local k = mkey(user, p.mon)
      death_seq[k] = death_seq[k] or {}
      if not death_seq[k][p.deaths or 0] then death_seq[k][p.deaths or 0] = ev.seq end
    elseif ev.type == corrections.TYPE then
      if corrections.validate(p) then
        corr[#corr + 1] = { seq = ev.seq, author = ev.user_id, p = p }
      else
        invalid[#invalid + 1] = ev.seq
      end
    end
  end
  -- reverts: scan newest first; a reverted revert does not revert anything
  local reverted = {}
  for i = #corr, 1, -1 do
    local c = corr[i]
    if c.p.kind == "revert" and not reverted[c.seq] and c.p.target < c.seq then
      reverted[c.p.target] = true
    end
  end
  local effective = {}
  for _, c in ipairs(corr) do
    if c.p.kind ~= "revert" and not reverted[c.seq] then effective[#effective + 1] = c end
  end
  return catch_seq, death_seq, effective, invalid
end

local function new_vmon(owner, id, m)
  return {
    id = id, owner = owner, species = m.species, form = m.form, nickname = m.nickname,
    nicknamed = m.nicknamed, level = m.level, shiny = m.shiny == true, own_route = m.route,
    where = m.where or "box", hp = m.hp, mhp = m.mhp, base_gift = m.gift == true, why = m.why,
    deaths = m.deaths or 0, manual = 0, undone = 0, virtual = false,
  }
end

local function eff_deaths(vm) return vm.deaths + vm.manual end
local function own_dead(vm) return eff_deaths(vm) > vm.undone end
local function is_gift(vm)
  if vm.gift_override ~= nil then return vm.gift_override end
  return vm.base_gift or vm.entry_kind == "gift"
end

-- Build per-player working data and apply the effective corrections in seq order.
local function build_players(players, states, effective, catch_seq, death_seq)
  local pv = {}
  for _, pl in ipairs(players) do
    local st = state.ensure(util.copy(states[pl.id]))
    local w = { st = st, mons = {}, ids = {}, routes = util.copy(st.routes), reopened = {}, manual_missed = {} }
    for _, pid in ipairs(util.keys(st.mons)) do
      w.mons[pid] = new_vmon(pl.id, pid, st.mons[pid])
      w.ids[#w.ids + 1] = pid
    end
    for _, route in ipairs(util.keys(w.routes)) do
      local e = w.routes[route]
      local vm = e.status == "caught" and e.mon and w.mons[e.mon]
      if vm then vm.counted_route, vm.entry_kind = route, e.kind end
    end
    pv[pl.id] = w
  end

  for _, c in ipairs(effective) do
    local p, seq = c.p, c.seq
    local w = p.user and pv[p.user]
    local k = p.kind
    if k == "doesnt_count" and w then
      local vm = p.mon and w.mons[p.mon]
      if not vm and p.route and not p.mon then
        local e = w.routes[p.route]
        if e and e.status == "caught" and e.mon then vm = w.mons[e.mon] end
        if not vm or vm.counted_route ~= p.route then vm = nil end
        if not vm then w.reopened[p.route], w.manual_missed[p.route] = true, nil end
      end
      if vm then vm.excluded, vm.why = true, p.reason or "manual" end
    elseif k == "mark_missed" and w then
      w.reopened[p.route], w.manual_missed[p.route] = nil, true
    elseif k == "set_group" and w and w.mons[p.mon] then
      local vm = w.mons[p.mon]
      vm.group_override = p.group ~= "none" and p.group or false
      vm.slot_seq = seq
    elseif k == "add" and w then
      local id = "add-" .. seq
      local vm = new_vmon(p.user, id, { species = p.species, form = p.form, nickname = p.nickname,
        level = p.level, shiny = p.shiny, route = p.route, where = p.state == "team" and "team" or "box",
        deaths = p.state == "dead" and 1 or 0 })
      vm.virtual, vm.slot_seq, vm.add_route = true, seq, p.route
      w.mons[id] = vm
      w.ids[#w.ids + 1] = id
      w.reopened[p.route], w.manual_missed[p.route] = nil, nil
      catch_seq[mkey(p.user, id)] = seq
      if p.state == "dead" then
        death_seq[mkey(p.user, id)] = { [1] = seq }
      end
    elseif k == "mark_dead" and w and w.mons[p.mon] then
      local vm = w.mons[p.mon]
      vm.manual = vm.manual + 1
      local dk = mkey(p.user, p.mon)
      death_seq[dk] = death_seq[dk] or {}
      death_seq[dk][eff_deaths(vm)] = seq
    elseif k == "set_gift" and w and w.mons[p.mon] then
      w.mons[p.mon].gift_override = p.gift
    elseif k == "undo_death" then
      for _, e in ipairs(p.undone) do
        local ow = pv[e.owner]
        local vm = ow and ow.mons[e.mon]
        if vm and e.deaths > vm.undone then vm.undone = e.deaths end
      end
    end
  end
  return pv
end

-- Claim route slots (route x player -> mon). Counted mons first, then moved mons, then hand-added.
local function assign_slots(players, pv)
  for _, pl in ipairs(players) do
    local w = pv[pl.id]
    w.slots = {}
    local function claim(vm, route)
      if w.slots[route] then return false end
      w.slots[route], vm.slot = vm, route
      return true
    end
    for _, id in ipairs(w.ids) do
      local vm = w.mons[id]
      if not vm.virtual and not vm.excluded and vm.group_override == nil and vm.counted_route then
        claim(vm, vm.counted_route)
      end
    end
    for _, id in ipairs(w.ids) do
      local vm = w.mons[id]
      if not vm.virtual and not vm.excluded and vm.group_override ~= nil then
        if vm.group_override == false then
          if vm.counted_route and claim(vm, vm.counted_route) then vm.unlinked = true end
        elseif not claim(vm, vm.group_override) then
          vm.group_conflict = true
        end
      end
    end
    for _, id in ipairs(w.ids) do
      local vm = w.mons[id]
      if vm.virtual and not vm.excluded then
        if not claim(vm, vm.add_route) then vm.why = vm.why or "extra" end
      end
    end
  end
end

local function cell_state(w, route)
  local vm = w.slots[route]
  if vm then return "caught", vm end
  if w.manual_missed[route] then return "missed" end
  local e = w.routes[route]
  if e and not w.reopened[route] then
    if e.status == "missed" then return "missed" end
    if e.status == "encounter" then return "encounter", nil, e end
  end
  return "open"
end

--- view(run, states, events, cfg) -> table
---   run     fb.run.current() result (participants, settings)
---   states  user_id -> own state of this plugin (fb.run.states())
---   events  run events (fb.run.events), ascending by seq; other event types are ignored
---   cfg     rules.parse() result; nil = parse from `run`
--- See docs/architecture.md for the result fields.
function V.view(run, states, events, cfg)
  run, states = run or {}, states or {}
  cfg = cfg and rules.normalize(cfg) or rules.parse(run)
  local soul = cfg.mode == "soullink"

  local players = {}
  for _, p in ipairs(run.participants or {}) do
    if type(p) == "table" and p.user_id and joined(p) then
      players[#players + 1] = { id = p.user_id, name = p.name or p.user_name or p.user_id,
                                color = p.color, game_id = p.game_id }
    end
  end
  if #players == 0 then
    for _, uid in ipairs(util.keys(states)) do players[#players + 1] = { id = uid, name = uid } end
  end
  local pindex = {}
  for i, pl in ipairs(players) do pindex[pl.id] = i end

  local catch_seq, death_seq, effective, invalid = collect_events(events)
  local pv = build_players(players, states, effective, catch_seq, death_seq)
  assign_slots(players, pv)

  -- routes with any activity, plus the current places
  local route_set = {}
  for _, pl in ipairs(players) do
    local w = pv[pl.id]
    for r in pairs(w.slots) do route_set[r] = true end
    for r in pairs(w.routes) do route_set[r] = true end
    for r in pairs(w.manual_missed) do route_set[r] = true end
    if w.st.place.key then route_set[w.st.place.key] = true end
  end
  local route_keys = util.keys(route_set)
  table.sort(route_keys, oras.compare)

  -- groups
  local groups, group_of = {}, {}
  if soul then
    for _, r in ipairs(route_keys) do
      local members, missed, gift, nolink = {}, false, false, false
      for _, pl in ipairs(players) do
        local w = pv[pl.id]
        local vm = w.slots[r]
        if vm then
          members[#members + 1] = vm
          gift = gift or is_gift(vm)
          nolink = nolink or vm.unlinked == true
        elseif (cell_state(w, r)) == "missed" then
          missed = true
        end
      end
      if #members > 0 then
        local g = { route = r, members = {}, count = #members, complete = #members == #players }
        local any_dead = false
        for _, vm in ipairs(members) do if own_dead(vm) then any_dead = true end end
        if gift then g.state = "gift"
        elseif nolink then g.state = "nolink"
        elseif missed then g.state = "broken"
        elseif any_dead then g.state = "dead"
        elseif g.complete then g.state = "linked"
        else g.state = "open" end
        g.propagates = g.state == "linked" or g.state == "dead" or g.state == "open"
        g.mons = members
        groups[#groups + 1] = g
        group_of[r] = g
      end
    end
  end

  -- deaths (own and propagated), dead on arrival, completion order, numbers
  local function seq_of_catch(vm)
    local s = math.max(catch_seq[mkey(vm.owner, vm.id)] or 0, vm.slot_seq or 0)
    return s > 0 and s or nil
  end
  for _, g in ipairs(groups) do
    local died, completed, lacking = INF, 0, false
    for _, vm in ipairs(g.mons) do
      if own_dead(vm) then
        local s = (death_seq[mkey(vm.owner, vm.id)] or {})[eff_deaths(vm)]
        if s and s < died then died = s end
      end
      local s = seq_of_catch(vm)
      if s then completed = math.max(completed, s) else lacking = true end
    end
    g.died_seq = died < INF and died or nil
    g.completed_seq = (not lacking and completed > 0) and completed or nil
    for _, vm in ipairs(g.mons) do
      if g.propagates and g.state == "dead" then
        vm.dead = true
        vm.cause = own_dead(vm) and "own" or "linked"
        if vm.cause == "linked" and g.died_seq then
          local s = seq_of_catch(vm)
          vm.doa = s ~= nil and s > g.died_seq or nil
        end
      end
      vm.group_state = g.state
    end
  end
  local numbered = {}
  for _, g in ipairs(groups) do
    if g.complete and (g.state == "linked" or g.state == "dead") then numbered[#numbered + 1] = g end
  end
  table.sort(numbered, function(a, b)
    local sa, sb = a.completed_seq or INF, b.completed_seq or INF
    if sa ~= sb then return sa < sb end
    return oras.compare(a.route, b.route)
  end)
  for i, g in ipairs(numbered) do g.number = i end

  -- mon views, players
  local out_players, graveyard, hints = {}, {}, {}
  local stats = { deaths = 0, groups_dead = 0, groups_linked = 0, routes_done = 0, routes_total = 0,
                  badges_max = 0, alive = 0 }
  local function mon_view(vm)
    if not vm.dead and own_dead(vm) then vm.dead, vm.cause = true, "own" end
    local g = vm.slot and group_of[vm.slot]
    return {
      id = vm.id, owner = vm.owner, species = vm.species, form = vm.form, nickname = vm.nickname,
      nicknamed = vm.nicknamed, level = vm.level, shiny = vm.shiny, hp = vm.hp, mhp = vm.mhp,
      route = vm.slot or vm.own_route, where = vm.where, dead = vm.dead == true, cause = vm.cause,
      doa = vm.doa == true, deaths = eff_deaths(vm), gift = is_gift(vm), why = vm.why,
      excluded = vm.excluded == true, virtual = vm.virtual, counted = vm.slot ~= nil,
      group = (g and g.propagates) and g.route or nil, group_state = vm.group_state,
      group_number = (g and g.propagates) and g.number or nil,
    }
  end

  for i, pl in ipairs(players) do
    local w = pv[pl.id]
    local team, box, seen = {}, 0, {}
    local views = {}
    for _, id in ipairs(w.ids) do views[id] = mon_view(w.mons[id]) end
    local function add_team(id)
      local mv = views[id]
      if mv and mv.where == "team" and not seen[id] then seen[id] = true; team[#team + 1] = mv end
    end
    for _, id in ipairs(w.st.order) do add_team(id) end
    for _, id in ipairs(w.ids) do add_team(id) end
    local alive, dead = 0, 0
    for _, id in ipairs(w.ids) do
      local mv = views[id]
      if mv.where == "box" then box = box + 1 end
      if mv.dead then
        dead = dead + 1
        graveyard[#graveyard + 1] = {
          owner = pl.id, mon = id, species = mv.species, form = mv.form, nickname = mv.nickname,
          route = mv.route, group = mv.group, group_number = mv.group_number, cause = mv.cause,
          doa = mv.doa, deaths = mv.deaths, shiny = mv.shiny,
          seq = mv.cause == "own" and (death_seq[mkey(pl.id, id)] or {})[mv.deaths]
            or (mv.group and group_of[mv.group].died_seq) or nil,
          player_index = i,
        }
      elseif mv.where ~= "gone" then
        alive = alive + 1
      end
    end
    stats.alive = stats.alive + alive
    local place = w.st.place
    local place_view = { key = place.key, name = place.name, zone = place.zone, manual = place.manual == true }
    local badges = w.st.badges or 0
    if badges > stats.badges_max then stats.badges_max = badges end
    out_players[i] = {
      id = pl.id, name = pl.name, color = pl.color, game_id = pl.game_id, place = place_view,
      team = team, box_count = box, alive = alive, dead = dead, badges = badges,
      level_cap = cfg.rules.level_caps and oras.level_cap(badges) or nil, mons = views, ids = w.ids,
    }
  end
  stats.deaths = #graveyard
  table.sort(graveyard, function(a, b)
    local sa, sb = a.seq or INF, b.seq or INF
    if sa ~= sb then return sa < sb end
    if a.player_index ~= b.player_index then return a.player_index < b.player_index end
    return a.mon < b.mon
  end)
  for _, g in ipairs(groups) do
    if g.state == "dead" then stats.groups_dead = stats.groups_dead + 1 end
    if g.state == "linked" then stats.groups_linked = stats.groups_linked + 1 end
  end

  -- rows (route x player)
  local rows = {}
  for _, r in ipairs(route_keys) do
    local cells, done = {}, #players > 0
    for _, pl in ipairs(players) do
      local w = pv[pl.id]
      local st_, vm, e = cell_state(w, r)
      local cell = { state = st_ }
      if vm then
        local mv = out_players[pindex[pl.id]].mons[vm.id]
        cell.mon, cell.species, cell.nickname, cell.gift = vm.id, mv.species, mv.nickname, mv.gift
        if mv.dead then cell.state, cell.cause = "dead", mv.cause end
      elseif e then
        cell.species = e.species
      end
      if st_ == "open" or st_ == "encounter" then done = false end
      cells[pl.id] = cell
    end
    local g = group_of[r]
    rows[#rows + 1] = { route = r, order = oras.order_index(r), cells = cells, group = g and {
      route = g.route, state = g.state, number = g.number, complete = g.complete, count = g.count,
    } or nil, done = done }
    if done then stats.routes_done = stats.routes_done + 1 end
  end
  stats.routes_total = #oras.ROUTE_KEYS + 1
  for _, r in ipairs(route_keys) do
    if r:sub(1, 6) == "place:" then stats.routes_total = stats.routes_total + 1 end
  end

  -- place status per player (location card)
  local row_of = {}
  for _, row in ipairs(rows) do row_of[row.route] = row end
  for i, pl in ipairs(players) do
    local p = out_players[i].place
    local status
    if not p.key then
      status = (p.zone ~= nil or p.name ~= nil) and "no_route" or "unknown"
    else
      status = row_of[p.key] and row_of[p.key].cells[pl.id].state or "open"
      if status == "dead" then status = "caught" end
    end
    p.status = status
  end

  -- group views for the UI (members carry what undo_death needs)
  local group_views = {}
  for _, g in ipairs(groups) do
    local members = {}
    for _, vm in ipairs(g.mons) do
      members[#members + 1] = { owner = vm.owner, id = vm.id, species = vm.species,
        nickname = vm.nickname, deaths = eff_deaths(vm), dead = vm.dead == true, cause = vm.cause,
        doa = vm.doa == true }
    end
    local gv = { route = g.route, state = g.state, number = g.number, complete = g.complete,
                 count = g.count, members = members, died_seq = g.died_seq, completed_seq = g.completed_seq }
    group_views[#group_views + 1] = gv
    if row_of[g.route] and row_of[g.route].group then row_of[g.route].group = gv end
  end
  table.sort(group_views, function(a, b)
    local na, nb = a.number or INF, b.number or INF
    if na ~= nb then return na < nb end
    return oras.compare(a.route, b.route)
  end)

  -- hints
  local r = cfg.rules
  for i, pl in ipairs(players) do
    local op = out_players[i]
    for _, id in ipairs(op.ids) do
      local mv = op.mons[id]
      local alive = not mv.dead and mv.where ~= "gone" and not mv.excluded and not mv.virtual
      if alive and r.nickname_required and mv.counted and not mv.gift
         and (mv.nickname == nil or mv.nickname == "" or mv.nicknamed == false) then
        hints[#hints + 1] = { code = "nickname_missing", user = pl.id, mon = id, route = mv.route, player_index = i }
      end
      if alive and r.level_caps and mv.where == "team" and op.level_cap and mv.level and mv.level > op.level_cap then
        hints[#hints + 1] = { code = "level_cap", user = pl.id, mon = id, level = mv.level,
                              cap = op.level_cap, player_index = i }
      end
      if alive and soul and r.only_linked_in_team and mv.where == "team" then
        local g = mv.group and group_of[mv.group]
        if not g or (g.state ~= "linked" and g.state ~= "open") then
          hints[#hints + 1] = { code = "unlinked_in_team", user = pl.id, mon = id, route = mv.route, player_index = i }
        elseif g.state == "linked" then
          for _, pm in ipairs(g.mons) do
            if pm.owner ~= pl.id and pm.where ~= "team" then
              hints[#hints + 1] = { code = "partner_not_in_team", user = pl.id, mon = id, route = mv.route,
                                    partner = pm.owner, partner_mon = pm.id, player_index = i }
            end
          end
        end
      end
    end
  end

  return {
    mode = cfg.mode, rules = cfg.rules, players = out_players, rows = rows, groups = group_views,
    graveyard = graveyard, stats = stats, hints = hints, invalid_corrections = invalid,
  }
end

return V

end
__mod["ui.board"] = function(...)
-- Hub run board (design 5gh): compact read-only tree for fb.run.setBoard.
local common = require("ui.common")
local oras = require("data.oras")

local M = {}

M.MAX_ROUTE_ROWS = 60
M.MAX_GRAVE_ROWS = 40

function M.build(ctx)
  local tr, view, run = ctx.tr, ctx.view, ctx.run
  local players = {}
  for i, p in ipairs(view.players) do
    players[#players + 1] = { id = "bp" .. i, title = p.name,
      sub = tr("board_player_sub", { place = common.place_label(p.place, tr), alive = p.alive, dead = p.dead, badges = p.badges }),
      tone = nil }
  end
  local columns = { tr("col_route") }
  for _, p in ipairs(view.players) do columns[#columns + 1] = p.name end
  columns[#columns + 1] = tr("col_group")
  local rows = {}
  for _, r in ipairs(view.rows) do
    if #rows < M.MAX_ROUTE_ROWS then
      local cells = { oras.label(r.route, tr) }
      for _, p in ipairs(view.players) do cells[#cells + 1] = common.cell_text(r.cells[p.id], tr) end
      cells[#cells + 1] = (r.group and r.group.number) and tr("group_n", { n = r.group.number }) or common.group_state_text(r.group, tr)
      rows[#rows + 1] = { cells = cells }
    end
  end
  local grave = {}
  for i, g in ipairs(view.graveyard) do
    if i <= M.MAX_GRAVE_ROWS then
      grave[#grave + 1] = { id = "bg" .. i, title = "✕ " .. common.mon_name(g),
        sub = tr("grave_sub", { route = g.route and oras.label(g.route, tr) or "?", player = common.name_of(view, g.owner) }), tone = "neutral" }
    end
  end
  local kids = {
    { type = "row", id = "b-head", gap = 8, align = "center", children = {
      { type = "text", id = "b-name", text = run.name or "", style = "title" },
      { type = "badge", id = "b-mode", text = common.mode_text(view, tr), tone = "info" },
      { type = "stat", id = "b-deaths", label = tr("stat_deaths"), value = tostring(view.stats.deaths) },
      { type = "stat", id = "b-routes", label = tr("stat_routes"), value = view.stats.routes_done .. " / " .. view.stats.routes_total },
    } },
    { type = "section", id = "b-players", title = tr("board_players"), children = { { type = "list", id = "b-plist", rows = players } } },
  }
  if #rows > 0 then
    kids[#kids + 1] = { type = "section", id = "b-routes-s", title = tr("tab_routes", { n = #view.rows }),
      children = { { type = "table", id = "b-routes", columns = columns, rows = rows } } }
  end
  if #grave > 0 then
    kids[#kids + 1] = { type = "section", id = "b-grave-s", title = tr("grave_title", { n = #view.graveyard }),
      children = { { type = "list", id = "b-grave", rows = grave } } }
  end
  return { type = "column", id = "board", gap = 12, children = kids }
end

return M

end
__mod["ui.common"] = function(...)
-- Shared helpers for the UI builders. Builders are pure: they take a context
--   ctx = { view, run, me, ui, tr, readonly, now, events }
-- and return fb.ui block trees. Only tones, sizes and player numbers are used, never colors.
local oras = require("data.oras")

local C = {}

--- Display name of a mon: its nickname, else "#<species id>" until the core provides names.
function C.mon_name(m)
  if m and type(m.nickname) == "string" and m.nickname ~= "" then return m.nickname end
  return "#" .. tostring(m and m.species or "?")
end

--- Player number 1..8 (identity color): participant color 0..7 + 1, else the list position.
function C.color(p, i)
  if math.type(p.color) == "integer" and p.color >= 0 and p.color <= 7 then return p.color + 1 end
  return math.min(math.max(i or 1, 1), 8)
end

function C.initial(name)
  name = tostring(name or "?")
  local n = utf8.offset(name, 2) or (#name + 1)
  local s = name:sub(1, n - 1):upper()
  return s ~= "" and s or "?"
end

function C.index_of(view, id)
  for i, p in ipairs(view.players) do if p.id == id then return i, p end end
  return nil
end

function C.player(view, id)
  local _, p = C.index_of(view, id)
  return p
end

function C.name_of(view, id)
  local p = C.player(view, id)
  return p and p.name or tostring(id)
end

function C.groups(view)
  local map = {}
  for _, g in ipairs(view.groups) do map[g.route] = g end
  return map
end

function C.row_of(view, route)
  for _, r in ipairs(view.rows) do if r.route == route then return r end end
  return nil
end

--- Place text: name read from the game if the core reported it, else the route label.
function C.place_label(place, tr)
  if place.name and place.name ~= "" then return place.name end
  if place.key then return oras.label(place.key, tr) end
  return tr("place_none")
end

local LOC_STATUS = { open = "open", encounter = "encounter", caught = "caught", missed = "missed" }
--- Status for the `location` block.
function C.loc_status(status) return LOC_STATUS[status] or "none" end

local TONE = { open = "info", encounter = "info", caught = "ok", missed = "neutral" }
function C.status_tone(status) return TONE[status] or "neutral" end

--- Short text of a cell of the routes matrix.
function C.cell_text(cell, tr)
  if cell.state == "open" then return tr("cell_open") end
  if cell.state == "encounter" then return tr("cell_encounter", { mon = "#" .. tostring(cell.species or "?") }) end
  if cell.state == "missed" then return tr("cell_missed") end
  local name = (cell.nickname and cell.nickname ~= "") and cell.nickname or ("#" .. tostring(cell.species or "?"))
  if cell.state == "dead" then return "✕ " .. name end
  return name
end

function C.group_state_text(g, tr)
  if not g then return tr("group_none") end
  return tr("group_state_" .. g.state)
end

--- Progress of HP as 0..1, or nil when unknown.
function C.hp_ratio(m)
  if type(m.hp) ~= "number" or type(m.mhp) ~= "number" or m.mhp <= 0 then return nil end
  return math.max(0, math.min(1, m.hp / m.mhp))
end

--- The own player entry of the view (or nil).
function C.me(ctx) return C.player(ctx.view, ctx.me) end

--- Whether writes are accepted: run starting/active and not the read-only run view.
function C.writable(run)
  return run and not run.view and (run.status == "starting" or run.status == "active") or false
end

function C.empty(tr, title_key, text_key)
  return { type = "empty", id = "empty", title = tr(title_key), text = tr(text_key) }
end

function C.mode_text(view, tr) return tr("mode_" .. view.mode) end

--- Number of alive mons of all players that are not gone.
function C.alive_of(p) return p.alive end

--- Short list of the other players' names in the run.
function C.others_names(view, me)
  local names = {}
  for _, p in ipairs(view.players) do if p.id ~= me then names[#names + 1] = p.name end end
  return table.concat(names, ", ")
end

return C

end
__mod["ui.corrections"] = function(...)
-- Inline section for the manual corrections 5f-1 .. 5f-5 (+ mark dead, gift, revert).
-- The state of the open form is ctx.ui.corr = { kind, user, route?, mon?, group?, reason?, species?,
-- nickname?, level?, state?, gift?, target?, note?, error? }; fields change through the actions
-- "cf:<field>", "corr_submit" posts the event, "corr_cancel" closes the form.
local common = require("ui.common")
local oras = require("data.oras")
local corrections = require("model.corrections")

local M = {}

local function route_options(tr, with_none)
  local opts = {}
  if with_none then opts[#opts + 1] = { value = "none", label = tr("c_group_none") } end
  opts[#opts + 1] = { value = oras.STARTER, label = oras.label(oras.STARTER, tr) }
  for _, k in ipairs(oras.ROUTE_KEYS) do opts[#opts + 1] = { value = k, label = oras.label(k, tr) } end
  return opts
end

--- Build the corrections payload spec from the form; returns spec or nil, error key.
function M.to_spec(corr)
  local k = corr.kind
  local spec
  if k == "doesnt_count" then
    spec = corrections.doesnt_count({ user = corr.user, route = corr.route, mon = corr.mon, reason = corr.reason or "wrong" })
  elseif k == "undo_death" then
    spec = corrections.undo_death({ group = corr.group, reason = corr.note, undone = corr.undone })
  elseif k == "set_group" then
    spec = corrections.set_group({ user = corr.user, mon = corr.mon, group = corr.group })
  elseif k == "add" then
    spec = corrections.add({ user = corr.user, route = corr.route, species = corr.species, nickname = corr.nickname,
      level = corr.level, state = corr.state or "box" })
  elseif k == "mark_missed" then
    spec = corrections.mark_missed({ user = corr.user, route = corr.route })
  elseif k == "mark_dead" then
    spec = corrections.mark_dead({ user = corr.user, mon = corr.mon, reason = corr.note })
  elseif k == "set_gift" then
    spec = corrections.set_gift({ user = corr.user, mon = corr.mon, gift = corr.gift ~= false })
  elseif k == "revert" then
    spec = corrections.revert({ target = corr.target, reason = corr.note })
  else
    return nil, "c_err_invalid"
  end
  if not corrections.validate_spec(spec) then return nil, "c_err_invalid" end
  return spec
end

local function buttons(ctx, corr)
  local tr = ctx.tr
  local danger = corr.kind == "undo_death" or corr.kind == "mark_dead"
  local submit = {
    type = "button", id = "corr-submit", label = tr("c_submit_" .. corr.kind), action = "corr_submit",
    variant = danger and "danger" or "primary",
  }
  if danger or corr.kind == "mark_missed" or corr.kind == "revert" then
    submit.confirm = { title = tr("c_confirm_title_" .. corr.kind), text = tr("c_confirm_text_" .. corr.kind),
      confirm_label = tr("c_submit_" .. corr.kind), danger = danger }
  end
  return { type = "row", id = "corr-buttons", gap = 8, children = {
    { type = "button", id = "corr-cancel", label = tr("cancel"), action = "corr_cancel", variant = "quiet" },
    submit,
  } }
end

--- Returns the section block, or nil when no form is open.
function M.section(ctx)
  local corr = ctx.ui.corr
  if not corr then return nil end
  local tr, view = ctx.tr, ctx.view
  local kids = {}
  local function add(b) kids[#kids + 1] = b end
  local k = corr.kind
  local route_label = corr.route and oras.label(corr.route, tr) or ""
  local others = common.others_names(view, ctx.me)

  if k == "doesnt_count" then
    add({ type = "text", id = "c-text", text = tr("c_dc_text", { route = route_label, others = others }), style = "meta" })
    add({ type = "segmented", id = "c-reason", action = "cf:reason", selected = corr.reason or "wrong", options = {
      { value = "dupe", label = tr("reason_dupe") }, { value = "shiny", label = tr("reason_shiny") },
      { value = "wrong", label = tr("reason_wrong") } } })
  elseif k == "undo_death" then
    add({ type = "text", id = "c-text", text = tr("c_undo_text", { n = corr.number or "?" }), style = "meta" })
    for i, m in ipairs(corr.members or {}) do
      add({ type = "text", id = "c-m" .. i, text = tr("c_undo_member", { player = common.name_of(view, m.owner),
        mon = common.mon_name(m) }), style = "body" })
    end
    add({ type = "textfield", id = "c-note", action = "cf:note", text = corr.note or "", placeholder = tr("c_reason_placeholder") })
  elseif k == "set_group" then
    add({ type = "text", id = "c-text", text = tr("c_group_text"), style = "meta" })
    local opts = route_options(tr, true)
    add({ type = "select", id = "c-group", action = "cf:group", options = opts, selected = corr.group or "none" })
  elseif k == "add" then
    add({ type = "text", id = "c-text", text = tr("c_add_text"), style = "meta" })
    add({ type = "select", id = "c-route", action = "cf:route", options = route_options(tr, false),
      selected = corr.route or oras.ROUTE_KEYS[1] })
    add({ type = "textfield", id = "c-species", action = "cf:species", text = corr.species and tostring(corr.species) or "",
      placeholder = tr("c_species_placeholder") })
    add({ type = "textfield", id = "c-nick", action = "cf:nickname", text = corr.nickname or "", placeholder = tr("c_nick_placeholder") })
    add({ type = "textfield", id = "c-level", action = "cf:level", text = corr.level and tostring(corr.level) or "",
      placeholder = tr("c_level_placeholder") })
    add({ type = "segmented", id = "c-state", action = "cf:state", selected = corr.state or "box", options = {
      { value = "box", label = tr("state_box") }, { value = "team", label = tr("state_team") },
      { value = "dead", label = tr("state_dead") } } })
  elseif k == "mark_missed" then
    add({ type = "text", id = "c-text", text = tr("c_missed_text", { route = route_label, others = others }), style = "meta" })
  elseif k == "mark_dead" then
    add({ type = "text", id = "c-text", text = tr("c_dead_text"), style = "meta" })
    add({ type = "textfield", id = "c-note", action = "cf:note", text = corr.note or "", placeholder = tr("c_reason_placeholder") })
  elseif k == "set_gift" then
    add({ type = "toggle", id = "c-gift", action = "cf:gift", label = tr("c_gift_label"), checked = corr.gift ~= false })
  elseif k == "revert" then
    add({ type = "text", id = "c-text", text = tr("c_revert_text", { seq = corr.target or "?" }), style = "meta" })
    add({ type = "textfield", id = "c-note", action = "cf:note", text = corr.note or "", placeholder = tr("c_reason_placeholder") })
  end
  if corr.error then
    add({ type = "text", id = "c-error", text = tr(corr.error), tone = "warning" })
  end
  add({ type = "text", id = "c-hint", text = tr("c_enter_hint"), style = "meta" })
  add(buttons(ctx, corr))
  return { type = "section", id = "corr", title = tr("c_title_" .. k), children = kids }
end

return M

end
__mod["ui.hud"] = function(...)
-- HUD widget (design 5c): compact place + status; expanded with the other players.
local common = require("ui.common")

local M = {}

function M.empty(tr)
  return { type = "text", id = "hud-empty", text = tr("hud_empty"), style = "meta" }
end

local function dot(status) return "●" end

--- ctx.ui.hud_expanded / ctx.hud_death (text, set for ~3 s after a linked death).
function M.build(ctx)
  local tr, view = ctx.tr, ctx.view
  local me = common.me(ctx)
  if not me then return M.empty(tr) end
  local status = me.place.status
  local compact = { type = "row", id = "hud-row", gap = 8, align = "center", children = {
    { type = "badge", id = "hud-sl", text = "SL", tone = "info" },
    { type = "text", id = "hud-place", text = common.place_label(me.place, tr), style = "body" },
    { type = "text", id = "hud-status", text = dot(status) .. " " .. tr("hud_status_" .. status),
      tone = common.status_tone(status), style = "meta" },
  } }
  local kids = { compact }
  if ctx.hud_death then
    kids[#kids + 1] = { type = "text", id = "hud-death", text = ctx.hud_death, style = "meta" }
  end
  if ctx.ui.hud_expanded or ctx.hud_death then
    local key = me.place.key
    local row = key and common.row_of(view, key)
    for i, p in ipairs(view.players) do
      if p.id ~= me.id then
        local cell = row and row.cells[p.id] or { state = "open" }
        kids[#kids + 1] = { type = "row", id = "hud-p" .. i, gap = 8, align = "center", children = {
          { type = "avatar", id = "hud-av" .. i, initial = common.initial(p.name), color = common.color(p, i), size = "s" },
          { type = "text", id = "hud-pt" .. i, text = tr("hud_other", { player = p.name, state = common.cell_text(cell, tr) }),
            style = "meta" },
        } }
      end
    end
  end
  return { type = "card", id = "hud", action = "hud_toggle", children = kids }
end

return M

end
__mod["ui.panel"] = function(...)
-- In-game panel (design 5b): run header, location card with place picker, encounter hint,
-- own team with link partners, graveyard, footer. Pure builder: panel.build(ctx) -> block.
local common = require("ui.common")
local corr_ui = require("ui.corrections")
local oras = require("data.oras")

local M = {}

function M.empty(tr)
  return { type = "column", gap = 12, children = {
    common.empty(tr, "empty_title", "empty_panel"),
  } }
end

local function header(ctx)
  local tr, run = ctx.tr, ctx.run
  local kids = {
    { type = "text", id = "h-eyebrow", text = tr("panel_eyebrow_" .. ctx.view.mode), style = "eyebrow" },
    { type = "text", id = "h-name", text = run.name or "", style = "heading" },
    { type = "button", id = "h-open", label = tr("open_run"), action = "open_run", variant = "quiet" },
  }
  if not common.writable(run) then
    table.insert(kids, 3, { type = "badge", id = "h-ro", text = tr("run_readonly_" .. tostring(run.status)), tone = "warning" })
  end
  return { type = "column", id = "header", gap = 4, children = kids }
end

local function others_on_place(ctx, me)
  local tr, view = ctx.tr, ctx.view
  local rows = {}
  local key = me.place.key
  if not key then return rows end
  local row = common.row_of(view, key)
  for i, p in ipairs(view.players) do
    if p.id ~= me.id and p.place.key == key then
      local cell = row and row.cells[p.id] or { state = "open" }
      rows[#rows + 1] = { type = "row", id = "o-" .. i, gap = 8, align = "center", children = {
        { type = "avatar", id = "o-av" .. i, initial = common.initial(p.name), color = common.color(p, i), size = "s" },
        { type = "text", id = "o-t" .. i, text = tr("other_on_place", { player = p.name, state = common.cell_text(cell, tr) }),
          style = "meta" },
      } }
    end
  end
  return rows
end

local function location(ctx, me)
  local tr = ctx.tr
  local status = me.place.status
  local sub_key = ({ open = "loc_open", encounter = "loc_encounter", caught = "loc_caught", missed = "loc_missed",
    no_route = "loc_no_route", unknown = "loc_unknown" })[status] or "loc_unknown"
  local row = me.place.key and common.row_of(ctx.view, me.place.key)
  local cell = row and row.cells[me.id]
  local sub
  if status == "caught" and cell then
    sub = common.cell_text(cell, tr)
  else
    sub = tr(sub_key)
  end
  local kids = others_on_place(ctx, me)
  return { type = "location", id = "loc", title = common.place_label(me.place, tr), sub = sub,
    status = common.loc_status(status), children = kids }
end

local function place_picker(ctx, me)
  local tr = ctx.tr
  local opts = { { value = oras.STARTER, label = oras.label(oras.STARTER, tr) } }
  for _, k in ipairs(oras.ROUTE_KEYS) do opts[#opts + 1] = { value = k, label = oras.label(k, tr) } end
  local selected = me.place.key
  local custom = selected and selected:match("^place:")
  if custom then opts[#opts + 1] = { value = selected, label = oras.label(selected, tr) } end
  local kids = {
    { type = "select", id = "place-select", options = opts, selected = selected, action = "place_select" },
    { type = "textfield", id = "place-text", action = "place_text", placeholder = tr("place_other"), text = "" },
  }
  if ctx.readonly then return nil end
  return { type = "column", id = "place-picker", gap = 4, children = kids }
end

local function encounter_hint(ctx, me)
  local tr = ctx.tr
  if me.place.status ~= "encounter" or ctx.readonly then return nil end
  local row = common.row_of(ctx.view, me.place.key)
  local cell = row and row.cells[me.id]
  return { type = "card", id = "enc", title = tr("enc_title"), children = {
    { type = "text", id = "enc-text", text = tr("enc_text", { mon = "#" .. tostring(cell and cell.species or "?") }), style = "meta" },
    { type = "button", id = "enc-no", label = tr("doesnt_count"), action = "dc_open", variant = "quiet" },
  } }
end

local function team(ctx, me)
  local tr = ctx.tr
  local groups = common.groups(ctx.view)
  local kids = {}
  for i, m in ipairs(me.team) do
    local title = common.mon_name(m) .. (m.level and (" · " .. tr("level_short", { n = m.level })) or "")
    if m.dead then title = "✕ " .. title end
    local c = { { type = "text", id = "m-t" .. i, text = title, style = "body", tone = m.dead and "neutral" or nil } }
    local ratio = (not m.dead) and common.hp_ratio(m)
    if ratio then
      c[#c + 1] = { type = "bar", id = "m-hp" .. i, value = ratio, label = tr("hp_label", { hp = m.hp, max = m.mhp }) }
    end
    local g = m.group and groups[m.group]
    if g and g.count > 1 then
      local partners = {}
      for j, pm in ipairs(g.members) do
        if pm.owner ~= me.id then
          local idx, pl = common.index_of(ctx.view, pm.owner)
          partners[#partners + 1] = { type = "avatar", id = "m-p" .. i .. "-" .. j,
            initial = common.initial(pl and pl.name), color = common.color(pl or {}, idx), size = "s" }
          partners[#partners + 1] = { type = "text", id = "m-pt" .. i .. "-" .. j,
            text = (pm.dead and "✕ " or "") .. common.mon_name(pm), style = "meta" }
        end
      end
      c[#c + 1] = { type = "row", id = "m-pr" .. i, gap = 8, align = "center", children = partners }
    end
    if not m.dead and not ctx.readonly then
      c[#c + 1] = { type = "button", id = "m-dead" .. i, label = tr("mark_dead"), action = "mark_dead", value = m.id,
        variant = "quiet", confirm = { title = tr("c_confirm_title_mark_dead"), text = tr("c_confirm_text_mark_dead"),
          confirm_label = tr("c_submit_mark_dead"), danger = true } }
    end
    kids[#kids + 1] = { type = "column", id = "mon" .. i, gap = 4, children = c }
  end
  if #kids == 0 then kids[1] = { type = "text", id = "team-empty", text = tr("team_empty"), style = "meta" } end
  return { type = "section", id = "team", title = tr("team_title", { n = #me.team }), children = kids }
end

local function graveyard(ctx)
  local tr, view = ctx.tr, ctx.view
  local open = ctx.ui.grave_open
  local kids = { { type = "chip", id = "grave-chip", text = tr("grave_title", { n = #view.graveyard }),
    action = "grave_toggle", selected = open and true or false } }
  if open then
    local rows = {}
    for i, g in ipairs(view.graveyard) do
      rows[i] = { id = "g" .. i, title = "✕ " .. common.mon_name(g),
        sub = tr("grave_sub", { route = g.route and oras.label(g.route, tr) or "?", player = common.name_of(view, g.owner) }),
        tone = "neutral" }
    end
    if #rows > 0 then kids[#kids + 1] = { type = "list", id = "grave-list", rows = rows } end
  end
  return { type = "column", id = "grave", gap = 4, children = kids }
end

local function footer(ctx, me)
  local tr = ctx.tr
  local opts = {}
  for n = 0, 8 do opts[#opts + 1] = { value = n, label = tostring(n) } end
  local kids = { { type = "stat", id = "badges", label = tr("badges"), value = tostring(me.badges) .. " / 8" } }
  if not ctx.readonly then
    kids[#kids + 1] = { type = "select", id = "badges-select", options = opts, selected = me.badges, action = "badges_select" }
  end
  if me.level_cap then
    kids[#kids + 1] = { type = "text", id = "cap", text = tr("next_cap", { n = me.level_cap }), style = "meta" }
  end
  kids[#kids + 1] = { type = "button", id = "f-open", label = tr("run_screen"), action = "open_run", variant = "secondary" }
  return { type = "column", id = "footer", gap = 8, children = kids }
end

--- ctx.view / ctx.run required.
function M.build(ctx)
  local me = common.me(ctx)
  if not me then
    return { type = "column", gap = 12, children = { header(ctx), common.empty(ctx.tr, "no_player_title", "no_player_text") } }
  end
  local kids = { header(ctx), location(ctx, me) }
  local picker = place_picker(ctx, me)
  if picker then kids[#kids + 1] = picker end
  local hint = encounter_hint(ctx, me)
  if hint then kids[#kids + 1] = hint end
  local corr = corr_ui.section(ctx)
  if corr then kids[#kids + 1] = corr end
  kids[#kids + 1] = team(ctx, me)
  kids[#kids + 1] = graveyard(ctx)
  kids[#kids + 1] = footer(ctx, me)
  return { type = "column", id = "panel", gap = 12, children = kids }
end

return M

end
__mod["ui.screen"] = function(...)
-- Run screen (design 5e), shown in the in-game screen slot: tabs Routes | Team & box | Graveyard |
-- Event log (Map first only when route coordinates exist: drawn default F hides it otherwise).
local common = require("ui.common")
local corr_ui = require("ui.corrections")
local oras = require("data.oras")

local M = {}

M.LOG_LIMIT = 100

function M.empty(tr)
  return { type = "column", gap = 12, children = { common.empty(tr, "empty_title", "empty_screen") } }
end

function M.has_map() return next(oras.COORDS) ~= nil end

local function header(ctx)
  local tr, view, run = ctx.tr, ctx.view, ctx.run
  local players = {}
  for i, p in ipairs(view.players) do
    players[#players + 1] = { type = "row", id = "ph" .. i, gap = 8, align = "center", children = {
      { type = "avatar", id = "ph-av" .. i, initial = common.initial(p.name), color = common.color(p, i), size = "m" },
      { type = "text", id = "ph-t" .. i, text = p.name .. " · " .. common.place_label(p.place, tr), style = "body" },
    } }
  end
  local s = view.stats
  return { type = "column", id = "head", gap = 8, children = {
    { type = "row", id = "head-row", gap = 8, align = "center", children = {
      { type = "text", id = "head-name", text = run.name or "", style = "title" },
      { type = "badge", id = "head-status", text = tr("run_status_" .. tostring(run.status)) .. " · " .. common.mode_text(view, tr),
        tone = common.writable(run) and "info" or "warning" },
    } },
    { type = "column", id = "head-players", gap = 4, children = players },
    { type = "grid", id = "head-stats", columns = 3, gap = 8, children = {
      { type = "stat", id = "st-deaths", label = tr("stat_deaths"), value = tostring(s.deaths) },
      { type = "stat", id = "st-routes", label = tr("stat_routes"), value = s.routes_done .. " / " .. s.routes_total },
      { type = "stat", id = "st-badges", label = tr("stat_badges"), value = tostring(s.badges_max) },
    } },
  } }
end

local function find_mine(ctx, route)
  local me = common.me(ctx)
  if not me then return nil end
  for _, id in ipairs(me.ids) do
    local m = me.mons[id]
    if m.route == route and m.counted then return m end
  end
  return nil
end

local function route_detail(ctx)
  local tr, view = ctx.tr, ctx.view
  local route = ctx.ui.selected_route
  local row = route and common.row_of(view, route)
  if not row then return nil end
  local g = row.group
  local kids = { { type = "text", id = "rd-status", text = common.group_state_text(g, tr) .. (g and g.number and (" · " .. tr("group_n", { n = g.number })) or ""),
    style = "meta" } }
  if not ctx.readonly then
    local acts = {
      { type = "button", id = "rd-missed", label = tr("mark_missed"), action = "missed_open", value = route, variant = "quiet" },
      { type = "button", id = "rd-dc", label = tr("doesnt_count"), action = "dc_open", value = route, variant = "quiet" },
    }
    if g and g.state == "dead" then
      acts[#acts + 1] = { type = "button", id = "rd-undo", label = tr("undo_death"), action = "undo_open", value = route, variant = "quiet" }
    end
    local mine = find_mine(ctx, route)
    if mine then
      acts[#acts + 1] = { type = "button", id = "rd-group", label = tr("change_group"), action = "group_open", value = mine.id, variant = "quiet" }
    end
    kids[#kids + 1] = { type = "row", id = "rd-acts", gap = 8, children = acts }
  end
  return { type = "section", id = "route-detail", title = oras.label(route, tr), children = kids }
end

local function routes_page(ctx)
  local tr, view = ctx.tr, ctx.view
  local filter = ctx.ui.routes_filter or "all"
  local n_open, n_done = 0, 0
  for _, r in ipairs(view.rows) do if r.done then n_done = n_done + 1 else n_open = n_open + 1 end end
  local columns = { tr("col_route") }
  for _, p in ipairs(view.players) do columns[#columns + 1] = p.name end
  columns[#columns + 1] = tr("col_group")
  columns[#columns + 1] = tr("col_status")
  local rows = {}
  for _, r in ipairs(view.rows) do
    if filter == "all" or (filter == "open" and not r.done) or (filter == "done" and r.done) then
      local cells = { oras.label(r.route, tr) }
      for _, p in ipairs(view.players) do cells[#cells + 1] = common.cell_text(r.cells[p.id], tr) end
      cells[#cells + 1] = (r.group and r.group.number) and tr("group_n", { n = r.group.number }) or "—"
      cells[#cells + 1] = common.group_state_text(r.group, tr)
      rows[#rows + 1] = { cells = cells, action = "route_select", value = r.route }
    end
  end
  local kids = {
    { type = "row", id = "rf", gap = 8, align = "center", children = {
      { type = "chip", id = "rf-all", text = tr("filter_all", { n = #view.rows }), action = "rf:all", selected = filter == "all" },
      { type = "chip", id = "rf-open", text = tr("filter_open", { n = n_open }), action = "rf:open", selected = filter == "open" },
      { type = "chip", id = "rf-done", text = tr("filter_done", { n = n_done }), action = "rf:done", selected = filter == "done" },
    } },
  }
  if not ctx.readonly then
    kids[#kids + 1] = { type = "button", id = "add-open", label = tr("add_by_hand"), action = "add_open", variant = "secondary" }
  end
  if #rows > 0 then
    kids[#kids + 1] = { type = "table", id = "routes-table", columns = columns, rows = rows }
  else
    kids[#kids + 1] = { type = "text", id = "routes-empty", text = tr("routes_empty"), style = "meta" }
  end
  local d = route_detail(ctx)
  if d then kids[#kids + 1] = d end
  return { type = "column", id = "page-routes", gap = 12, children = kids }
end

local function team_page(ctx)
  local tr, view = ctx.tr, ctx.view
  local secs = {}
  for i, p in ipairs(view.players) do
    local kids = {}
    for j, m in ipairs(p.team) do
      local title = (m.dead and "✕ " or "") .. common.mon_name(m) .. (m.level and (" · " .. tr("level_short", { n = m.level })) or "")
      local c = { { type = "text", id = "tm" .. i .. "-" .. j, text = title, style = "body" } }
      local ratio = (not m.dead) and common.hp_ratio(m)
      if ratio then c[#c + 1] = { type = "bar", id = "tm-hp" .. i .. "-" .. j, value = ratio, label = tr("hp_label", { hp = m.hp, max = m.mhp }) } end
      if p.id == ctx.me and not ctx.readonly then
        c[#c + 1] = { type = "row", id = "tm-a" .. j, gap = 8, children = {
          { type = "button", id = "tm-g" .. j, label = tr("change_group"), action = "group_open", value = m.id, variant = "quiet" },
          { type = "button", id = "tm-gift" .. j, label = tr("mark_gift"), action = "gift_open", value = m.id, variant = "quiet" },
          (not m.dead) and { type = "button", id = "tm-d" .. j, label = tr("mark_dead"), action = "dead_open", value = m.id, variant = "quiet" } or nil,
        } }
      end
      kids[#kids + 1] = { type = "column", id = "tmc" .. i .. "-" .. j, gap = 4, children = c }
    end
    if #p.team == 0 then kids[1] = { type = "text", id = "tm-empty" .. i, text = tr("team_empty"), style = "meta" } end
    local rows = {}
    for _, id in ipairs(p.ids) do
      local m = p.mons[id]
      if m.where == "box" then
        rows[#rows + 1] = { id = "b" .. id, title = (m.dead and "✕ " or "") .. common.mon_name(m),
          sub = m.route and oras.label(m.route, tr) or nil, tone = m.dead and "neutral" or nil }
      end
    end
    kids[#kids + 1] = { type = "text", id = "box-count" .. i, text = tr("box_count", { n = p.box_count }), style = "eyebrow" }
    if #rows > 0 then kids[#kids + 1] = { type = "list", id = "box-list" .. i, rows = rows } end
    secs[#secs + 1] = { type = "section", id = "pl" .. i, title = tr("team_player", { player = p.name, place = common.place_label(p.place, tr) }),
      children = kids }
  end
  return { type = "column", id = "page-team", gap = 12, children = secs }
end

local function graveyard_page(ctx)
  local tr, view = ctx.tr, ctx.view
  if #view.graveyard == 0 then
    return { type = "column", id = "page-grave", gap = 12, children = { { type = "text", id = "grave-empty", text = tr("grave_empty"), style = "meta" } } }
  end
  local rows = {}
  for _, g in ipairs(view.graveyard) do
    local cause = g.doa and tr("cause_doa") or tr("cause_" .. tostring(g.cause))
    rows[#rows + 1] = { cells = { common.mon_name(g), common.name_of(view, g.owner), g.route and oras.label(g.route, tr) or "—",
      cause, g.group_number and tr("group_n", { n = g.group_number }) or "—" },
      action = g.group and "undo_open" or nil, value = g.group }
  end
  return { type = "column", id = "page-grave", gap = 12, children = {
    { type = "table", id = "grave-table", columns = { tr("col_creature"), tr("col_owner"), tr("col_route"), tr("col_cause"), tr("col_group") }, rows = rows },
    { type = "text", id = "grave-hint", text = tr("grave_hint"), style = "meta" },
  } }
end

local function event_text(ctx, ev)
  if type(ev.text) == "string" and ev.text ~= "" then return ev.text end
  return ctx.tr("log_type_" .. tostring(ev.type):gsub("[^%w]", "_"))
end

local function log_page(ctx)
  local tr, view = ctx.tr, ctx.view
  local filter = ctx.ui.log_filter or "all"
  local rows = {}
  local evs = ctx.events or {}
  for i = #evs, 1, -1 do
    local ev = evs[i]
    if ev.source ~= "hub" and (filter == "all" or ev.source == filter) and #rows < M.LOG_LIMIT then
      rows[#rows + 1] = {
        id = "e" .. ev.seq, title = event_text(ctx, ev),
        sub = tr("log_sub", { player = common.name_of(view, ev.user_id), source = tr("source_" .. tostring(ev.source)) }),
        meta = "#" .. ev.seq, tone = ev.source == "manual" and "warning" or nil,
        action = (ev.type == "soullink.correction" and not ctx.readonly) and "revert_open" or nil,
        value = ev.seq,
      }
    end
  end
  local kids = { { type = "row", id = "lf", gap = 8, children = {
    { type = "chip", id = "lf-all", text = tr("log_all"), action = "lf:all", selected = filter == "all" },
    { type = "chip", id = "lf-auto", text = tr("log_automatic"), action = "lf:automatic", selected = filter == "automatic" },
    { type = "chip", id = "lf-manual", text = tr("log_manual"), action = "lf:manual", selected = filter == "manual" },
  } } }
  if #rows > 0 then kids[#kids + 1] = { type = "list", id = "log-list", rows = rows }
  else kids[#kids + 1] = { type = "text", id = "log-empty", text = tr("log_empty"), style = "meta" } end
  return { type = "column", id = "page-log", gap = 12, children = kids }
end

local function map_page(ctx)
  local view = ctx.view
  local players, routes = {}, {}
  for i, p in ipairs(view.players) do
    local c = p.place.key and oras.COORDS[p.place.key]
    if c then
      players[#players + 1] = { id = p.id, initial = common.initial(p.name), color = common.color(p, i), x = c.x, y = c.y }
    end
  end
  for _, r in ipairs(view.rows) do
    local c = oras.COORDS[r.route]
    if c then
      routes[#routes + 1] = { id = r.route, x = c.x, y = c.y, area = c.area, number = r.group and r.group.number or nil, done = r.done }
    end
  end
  local map = { type = "map", id = "map", players = players, routes = routes, filter = ctx.ui.map_filter or "all",
    me = ctx.me, legend = true, action = "map_select" }
  if ctx.ui.map_src and oras.MAP_SIZE then
    map.image, map.image_w, map.image_h = ctx.ui.map_src, oras.MAP_SIZE.w, oras.MAP_SIZE.h
  end
  if ctx.ui.selected_route then map.selected = ctx.ui.selected_route end
  return { type = "column", id = "page-map", gap = 12, children = { map } }
end

--- Tab order for the current data: { "map"? , "routes", "team", "grave", "log" }.
function M.tab_ids()
  local ids = {}
  if M.has_map() then ids[#ids + 1] = "map" end
  for _, id in ipairs({ "routes", "team", "grave", "log" }) do ids[#ids + 1] = id end
  return ids
end

function M.build(ctx)
  local tr, view = ctx.tr, ctx.view
  local ids = M.tab_ids()
  local labels, pages = {}, {}
  local counts = { routes = #view.rows, grave = #view.graveyard, log = #(ctx.events or {}) }
  for i, id in ipairs(ids) do
    labels[i] = tr("tab_" .. id, { n = counts[id] or 0 })
    local builders = { map = map_page, routes = routes_page, team = team_page, grave = graveyard_page, log = log_page }
    pages[i] = builders[id](ctx)
  end
  local sel = math.min(math.max(ctx.ui.screen_tab or 1, 1), #ids)
  local kids = { header(ctx) }
  local corr = corr_ui.section(ctx)
  if corr then kids[#kids + 1] = corr end
  kids[#kids + 1] = { type = "tabs", id = "tabs", tabs = labels, selected = sel, action = "tab", children = pages }
  return { type = "column", id = "screen", gap = 16, children = kids }
end

return M

end
__mod["ui.tile"] = function(...)
-- Strip on a friend's Multiview tile (design 5d): "SL <place> · <n> alive" (first text row).
local common = require("ui.common")

local M = {}

--- player = view player entry of the tile's owner.
function M.build(tr, player)
  return { type = "text", id = "tile", text = tr("tile_strip", { place = common.place_label(player.place, tr), n = player.alive }),
    style = "meta" }
end

--- Match the host event `tiles` ({ id, player, user_id, game }) to view players: by `user_id` first
--- (empty string = unknown), by name (case-insensitive) as fallback. Returns { [tile id] = player }.
function M.match(tiles, view)
  local out = {}
  for _, t in ipairs(type(tiles) == "table" and tiles or {}) do
    if type(t) == "table" and type(t.id) == "string" and t.id:match("^[%w_.%-]+$") and #t.id <= 64 then
      local found
      if type(t.user_id) == "string" and t.user_id ~= "" then
        for _, p in ipairs(view.players) do
          if p.id == t.user_id then found = p; break end
        end
      end
      if not found and type(t.player) == "string" then
        for _, p in ipairs(view.players) do
          if tostring(p.name):lower() == t.player:lower() then found = p; break end
        end
      end
      out[t.id] = found
    end
  end
  return out
end

return M

end
require("main")
